const DEFAULT_ENDPOINT = "https://www.geeknow.top";
const LEGACY_ENDPOINT_KEY = "reference-atelier-endpoint";
const LEGACY_API_KEY = "reference-atelier-api-key";
const CONNECTIONS_KEY = "reference-atelier-api-connections";
const ACTIVE_CONNECTION_KEY = "reference-atelier-active-connection";
const DEFAULT_CONNECTIONS = [
  { id: "geeknow", name: "Geeknow", endpoint: DEFAULT_ENDPOINT, apiKey: "" },
  { id: "fmgo", name: "FMGO", endpoint: "https://api.fmgo.top", apiKey: "" },
  { id: "qilingze", name: "麒麟泽", endpoint: "https://api.qilingze.com/v1", apiKey: "" },
  { id: "seventoken", name: "Token超市", endpoint: "https://api.seventoken.shop/v1", apiKey: "" },
  { id: "lk888", name: "长风AI", endpoint: "https://api.lk888.ai", apiKey: "" },
  { id: "grsai", name: "Grsai", endpoint: "https://grsai.dakka.com.cn", apiKey: "" },
];
const QILINGZE_GPT25_MODEL = "GPT Image 2.5";
const SEVENTOKEN_UPSCALE_MODEL = "gpt-image-2-upscale";
const LK888_TT2_MODEL = "tt-image-2";
const LK888_TT25_MODEL = "tt-image-2.5";
const PROVIDER_MODELS = {
  geeknow: ["gpt-image-2", "gpt-image-2-pro", "gpt-image-2-vip", "gpt-image-2.5-sunburst"],
  fmgo: ["gpt-image-2", "gpt-image-2-plus", "gpt-image-2-pro", "gpt-image-2.5-flare", "gpt-image-2.5-sunburst"],
  qilingze: [QILINGZE_GPT25_MODEL, "gpt-image-2", "gpt-image-2-vip", "nano-banana-2"],
  seventoken: [SEVENTOKEN_UPSCALE_MODEL],
  lk888: [LK888_TT2_MODEL, LK888_TT25_MODEL],
  grsai: ["gpt-image-2", "gpt-image-2-vip", "gpt-image-2.5", "gpt-image-2.5-flare", "gpt-image-2.5-sunburst"],
};
const FMGO_ASPECT_RATIOS = ["1:1", "16:9", "9:16", "2:3", "3:2", "4:3", "3:4"];
const FMGO_25_MODELS = ["gpt-image-2.5-flare", "gpt-image-2.5-sunburst"];
const GENERATION_SETTINGS_KEY = "reference-atelier-generation-settings";
const PROMPT_DRAFT_KEY = "reference-atelier-prompt-draft";
const REFERENCE_DB_NAME = "reference-atelier-storage";
const REFERENCE_DB_STORE = "reference-images";
const FAVORITE_DB_STORE = "favorite-images";
const BATCH_DB_STORE = "batch-workspace";
const BATCH_SETTINGS_KEY = "settings";
const DRAFT_META_PREFIX = "draft-meta:";
const DRAFT_DATA_PREFIX = "draft:";
const REFERENCE_DB_VERSION = 3;
const MAX_REFERENCES = 24;
const POLL_INTERVAL_MS = 3000;
const MAX_POLL_MS = 15 * 60 * 1000;
const FMGO_POLL_REQUEST_TIMEOUT_MS = 10000;
const IMAGE_FETCH_TIMEOUT_MS = 20000;

const connectionSelect = document.querySelector("#connectionSelect");
const connectionDot = document.querySelector("#connectionDot");
const connectionSettingsButton = document.querySelector("#connectionSettingsButton");
const connectionDialog = document.querySelector("#connectionDialog");
const connectionForm = document.querySelector("#connectionForm");
const connectionDialogTitle = document.querySelector("#connectionDialogTitle");
const endpointInput = document.querySelector("#endpointInput");
const keyInput = document.querySelector("#keyInput");
const connectionPresetHint = document.querySelector("#connectionPresetHint");
const closeConnectionDialogButton = document.querySelector("#closeConnectionDialogButton");
const resetConnectionButton = document.querySelector("#resetConnectionButton");
const imageInput = document.querySelector("#imageInput");
const uploadBox = document.querySelector("#uploadBox");
const pageDropOverlay = document.querySelector("#pageDropOverlay");
const referenceList = document.querySelector("#referenceList");
const referenceCount = document.querySelector("#referenceCount");
const clearReferencesButton = document.querySelector("#clearReferencesButton");
const resultGrid = document.querySelector("#resultGrid");
const emptyState = document.querySelector("#emptyState");
const modelSelect = document.querySelector("#modelSelect");
const modelLabel = document.querySelector("#modelLabel");
const sizeSelect = document.querySelector("#sizeSelect");
const resolutionField = document.querySelector("#resolutionField");
const resolutionSelect = document.querySelector("#resolutionSelect");
const qualitySelect = document.querySelector("#qualitySelect");
const promptInput = document.querySelector("#promptInput");
const referenceModeSelect = document.querySelector("#referenceModeSelect");
const mentionMenu = document.querySelector("#mentionMenu");
const mentionBar = document.querySelector("#mentionBar");
const generateButton = document.querySelector("#generateButton");
const statusLine = document.querySelector("#statusLine");
const editTaskDialog = document.querySelector("#editTaskDialog");
const editTaskForm = document.querySelector("#editTaskForm");
const editTaskTitle = document.querySelector("#editTaskTitle");
const editTaskContext = document.querySelector("#editTaskContext");
const editTaskPrompt = document.querySelector("#editTaskPrompt");
const closeEditTaskDialogButton = document.querySelector("#closeEditTaskDialogButton");
const cancelEditTaskButton = document.querySelector("#cancelEditTaskButton");
const previewDialog = document.querySelector("#previewDialog");
const previewTitle = document.querySelector("#previewTitle");
const previewImage = document.querySelector("#previewImage");

let references = [];
let nextTaskId = 1;
let connectionProfiles = DEFAULT_CONNECTIONS.map((connection) => ({ ...connection }));
let activeConnectionId = "geeknow";
let modelByConnection = {};
let pageDragDepth = 0;
let mentionState = {
  activeIndex: 0,
  end: 0,
  items: [],
  open: false,
  start: 0,
};
const finishedImages = new Map();
const taskRecords = new Map();
let editingTaskId = "";
let referenceDatabasePromise = null;

const setStatus = (message) => {
  statusLine.textContent = message;
};

const escapeHtml = (value) =>
  String(value).replace(/[&<>"']/g, (char) => ({
    "&": "&amp;",
    "<": "&lt;",
    ">": "&gt;",
    '"': "&quot;",
    "'": "&#39;",
  })[char]);

const formatBytes = (bytes) => {
  if (!bytes) return "0 KB";
  if (bytes < 1024 * 1024) return `${Math.max(1, Math.round(bytes / 1024))} KB`;
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
};

const sleep = (ms) => new Promise((resolve) => window.setTimeout(resolve, ms));

const persistGenerationSettings = () => {
  try {
    if (modelSelect.value) {
      modelByConnection[activeConnectionId] = modelSelect.value;
    }
    localStorage.setItem(GENERATION_SETTINGS_KEY, JSON.stringify({
      modelByConnection,
      quality: qualitySelect.value,
      referenceMode: referenceModeSelect?.value || "auto",
      resolution: resolutionSelect?.value || "1K",
      size: sizeSelect.value,
    }));
  } catch {
    // The controls remain usable when browser storage is unavailable.
  }
};

const persistPromptDraft = () => {
  try {
    if (promptInput.value.trim()) {
      localStorage.setItem(PROMPT_DRAFT_KEY, promptInput.value);
    } else {
      localStorage.removeItem(PROMPT_DRAFT_KEY);
    }
  } catch {
    // The prompt remains usable when browser storage is unavailable.
  }
};

const restoreGenerationState = () => {
  const restoreSelect = (select, value) => {
    if (value && [...select.options].some((option) => option.value === value)) {
      select.value = value;
    }
  };

  try {
    const settings = JSON.parse(localStorage.getItem(GENERATION_SETTINGS_KEY) || "{}");
    modelByConnection = settings.modelByConnection && typeof settings.modelByConnection === "object"
      ? { ...settings.modelByConnection }
      : {};
    if (settings.model && !modelByConnection[activeConnectionId]) {
      modelByConnection[activeConnectionId] = settings.model;
    }
    renderModelOptions();
    restoreSelect(sizeSelect, settings.size);
    if (resolutionSelect) restoreSelect(resolutionSelect, settings.resolution);
    restoreSelect(qualitySelect, settings.quality);
    if (referenceModeSelect) restoreSelect(referenceModeSelect, settings.referenceMode);

    const savedPrompt = localStorage.getItem(PROMPT_DRAFT_KEY) || "";
    if (savedPrompt.trim()) {
      promptInput.value = savedPrompt;
    } else {
      localStorage.removeItem(PROMPT_DRAFT_KEY);
    }
  } catch {
    // Keep the default controls when saved data is invalid or unavailable.
    modelByConnection = {};
    renderModelOptions();
  }
};

const openReferenceDatabase = () => {
  if (!window.indexedDB) {
    return Promise.reject(new Error("当前浏览器不支持 IndexedDB。"));
  }

  if (!referenceDatabasePromise) {
    referenceDatabasePromise = new Promise((resolve, reject) => {
      const request = indexedDB.open(REFERENCE_DB_NAME, REFERENCE_DB_VERSION);
      request.onupgradeneeded = () => {
        const database = request.result;
        if (!database.objectStoreNames.contains(REFERENCE_DB_STORE)) {
          database.createObjectStore(REFERENCE_DB_STORE, { keyPath: "position" });
        }
        if (!database.objectStoreNames.contains(FAVORITE_DB_STORE)) {
          database.createObjectStore(FAVORITE_DB_STORE, { keyPath: "id" });
        }
        if (!database.objectStoreNames.contains(BATCH_DB_STORE)) {
          database.createObjectStore(BATCH_DB_STORE, { keyPath: "key" });
        }
      };
      request.onsuccess = () => {
        request.result.onversionchange = () => request.result.close();
        resolve(request.result);
      };
      request.onerror = () => reject(request.error || new Error("无法打开参考图本地存储。"));
      request.onblocked = () => reject(new Error("本地存储正在被旧页面占用，请关闭旧页面后重试。"));
    });
  }

  return referenceDatabasePromise;
};

const waitForTransaction = (transaction) => new Promise((resolve, reject) => {
  transaction.oncomplete = () => resolve();
  transaction.onerror = () => reject(transaction.error || new Error("本地存储失败。"));
  transaction.onabort = () => reject(transaction.error || new Error("本地存储已中止。"));
});

const persistReferences = async () => {
  const database = await openReferenceDatabase();
  const transaction = database.transaction(REFERENCE_DB_STORE, "readwrite");
  const store = transaction.objectStore(REFERENCE_DB_STORE);
  store.clear();

  references.forEach((ref, index) => {
    store.put({
      blob: ref.file.slice(0, ref.file.size, ref.file.type || "image/png"),
      lastModified: ref.file.lastModified || Date.now(),
      name: ref.file.name,
      position: index + 1,
      type: ref.file.type || "image/png",
    });
  });

  await waitForTransaction(transaction);
};

const restoreReferences = async () => {
  const database = await openReferenceDatabase();
  const transaction = database.transaction(REFERENCE_DB_STORE, "readonly");
  const request = transaction.objectStore(REFERENCE_DB_STORE).getAll();
  const records = await new Promise((resolve, reject) => {
    request.onsuccess = () => resolve(request.result || []);
    request.onerror = () => reject(request.error || new Error("无法读取已保存的参考图。"));
  });

  references.forEach((ref) => URL.revokeObjectURL(ref.previewUrl));
  references = records
    .sort((left, right) => left.position - right.position)
    .filter((record) => record.blob instanceof Blob)
    .map((record) => {
      const file = new File([record.blob], record.name || `reference-${record.position}.png`, {
        lastModified: record.lastModified || Date.now(),
        type: record.type || record.blob.type || "image/png",
      });
      return {
        error: "",
        file,
        id: record.position,
        mention: makeReferenceMention(record.position),
        previewUrl: URL.createObjectURL(file),
        publicUrl: "",
        uploadPromise: null,
        uploading: false,
      };
    });
  reindexReferences();
};

const normalizeEndpoint = (value) => {
  const raw = String(value || "").trim();
  if (!raw) return "";
  const withProtocol = /^https?:\/\//i.test(raw) ? raw : `https://${raw}`;
  const url = new URL(withProtocol);
  const pathname = url.pathname.replace(/\/+$/, "");
  return `${url.origin}${pathname}`;
};

const normalizeConnectionEndpoint = (connectionId, value) => {
  const endpoint = normalizeEndpoint(value);
  if (!endpoint) return "";
  const url = new URL(endpoint);
  if (connectionId === "geeknow" && url.hostname.toLowerCase() === "api.geeknow.ai") {
    return DEFAULT_ENDPOINT;
  }
  if (connectionId === "qilingze" && url.hostname.toLowerCase().endsWith("qilingze.com")) {
    const path = url.pathname.replace(/\/+$/, "").toLowerCase();
    if (!path || path === "/console") return `${url.origin}/v1`;
  }
  if (connectionId === "seventoken" && url.hostname.toLowerCase().endsWith("seventoken.shop")) {
    const path = url.pathname.replace(/\/+$/, "").toLowerCase();
    if (!path || path === "/custom/video-access-docs") return `${url.origin}/v1`;
  }
  if (connectionId === "lk888" && url.hostname.toLowerCase().endsWith("lk888.ai")) {
    if (url.hostname.toLowerCase() === "sf.lk888.ai") return "https://api.lk888.ai";
    const path = url.pathname.replace(/\/+$/, "").toLowerCase();
    if (!path || path === "/docs" || path === "/console" || path === "/v1") return url.origin;
  }
  if (connectionId === "grsai") {
    const hostname = url.hostname.toLowerCase();
    if (["grsai.com", "www.grsai.com", "grsai.ai", "www.grsai.ai"].includes(hostname)) {
      return "https://grsai.dakka.com.cn";
    }
    if (["grsaiapi.com", "grsai.dakka.com.cn"].includes(hostname) && url.pathname.toLowerCase() === "/v1") {
      return url.origin;
    }
  }
  return endpoint;
};

const getDefaultConnection = (id) =>
  DEFAULT_CONNECTIONS.find((connection) => connection.id === id) || DEFAULT_CONNECTIONS[0];

const persistConnections = () => {
  try {
    localStorage.setItem(CONNECTIONS_KEY, JSON.stringify(connectionProfiles));
    localStorage.setItem(ACTIVE_CONNECTION_KEY, activeConnectionId);
  } catch {
    // The current connection remains usable when browser storage is unavailable.
  }
};

const loadConnections = () => {
  let migratedConnectionId = "geeknow";

  try {
    const savedConnections = JSON.parse(localStorage.getItem(CONNECTIONS_KEY) || "null");
    if (Array.isArray(savedConnections)) {
      const oldCustomConnection = savedConnections.find((connection) => {
        if (connection?.id !== "custom") return false;
        try {
          return new URL(normalizeEndpoint(connection.endpoint)).hostname.toLowerCase().endsWith("qilingze.com");
        } catch {
          return false;
        }
      });
      connectionProfiles = DEFAULT_CONNECTIONS.map((fallback) => {
        const saved = savedConnections.find((connection) => connection?.id === fallback.id)
          || (fallback.id === "qilingze" ? oldCustomConnection : null)
          || {};
        let endpoint = fallback.endpoint;
        try {
          endpoint = normalizeConnectionEndpoint(fallback.id, saved.endpoint ?? fallback.endpoint);
        } catch {
          endpoint = fallback.endpoint;
        }
        return {
          id: fallback.id,
          name: fallback.name,
          endpoint,
          apiKey: String(saved.apiKey || "").trim(),
        };
      });
    } else {
      const savedLegacyEndpoint = localStorage.getItem(LEGACY_ENDPOINT_KEY) || DEFAULT_ENDPOINT;
      const legacyEndpoint = savedLegacyEndpoint === "https://www.geeknow.top"
        ? DEFAULT_ENDPOINT
        : normalizeEndpoint(savedLegacyEndpoint);
      const legacyKey = String(localStorage.getItem(LEGACY_API_KEY) || "").trim();
      const hostname = new URL(legacyEndpoint).hostname.toLowerCase();
      migratedConnectionId = hostname.endsWith("fmgo.top")
        ? "fmgo"
        : hostname.endsWith("qilingze.com")
          ? "qilingze"
        : hostname.endsWith("seventoken.shop")
          ? "seventoken"
        : hostname.endsWith("lk888.ai")
          ? "lk888"
        : hostname.endsWith("grsai.com") || hostname.endsWith("grsai.ai") || hostname.endsWith("dakka.com.cn")
          ? "grsai"
        : hostname.endsWith("geeknow.ai") || hostname.endsWith("geeknow.top")
          ? "geeknow"
          : "geeknow";
      const migratedConnection = connectionProfiles.find((connection) => connection.id === migratedConnectionId);
      migratedConnection.endpoint = normalizeConnectionEndpoint(migratedConnectionId, legacyEndpoint);
      migratedConnection.apiKey = legacyKey;
    }

    let savedActiveId = localStorage.getItem(ACTIVE_CONNECTION_KEY) || migratedConnectionId;
    if (savedActiveId === "custom") {
      savedActiveId = connectionProfiles.find((connection) => connection.id === "qilingze" && connection.apiKey)
        ? "qilingze"
        : "geeknow";
    }
    activeConnectionId = connectionProfiles.some((connection) => connection.id === savedActiveId)
      ? savedActiveId
      : "geeknow";
    persistConnections();
  } catch {
    connectionProfiles = DEFAULT_CONNECTIONS.map((connection) => ({ ...connection }));
    activeConnectionId = "geeknow";
  }
};

const getActiveConnection = () =>
  connectionProfiles.find((connection) => connection.id === activeConnectionId) || connectionProfiles[0];

const getApiKey = () => getActiveConnection()?.apiKey || "";

const getEndpoint = () => {
  try {
    return normalizeEndpoint(getActiveConnection()?.endpoint) || DEFAULT_ENDPOINT;
  } catch {
    return DEFAULT_ENDPOINT;
  }
};

const apiUrl = (path, endpointOverride = "") => {
  const endpoint = normalizeEndpoint(endpointOverride) || getEndpoint();
  const url = new URL(endpoint);
  const basePath = url.pathname.replace(/\/+$/, "");

  if (basePath.toLowerCase().endsWith("/v1") && path.startsWith("/v1/")) {
    return `${url.origin}${basePath}${path.slice(3)}`;
  }

  if (basePath.toLowerCase().endsWith("/v1") && path.startsWith("/api/")) {
    return `${url.origin}${path}`;
  }

  return `${endpoint}${path}`;
};

const getApiProvider = () => getActiveConnection()?.id || "geeknow";

const aspectRatioToSize = (aspectRatio, model, provider = getApiProvider()) => {
  if (provider === "qilingze") {
    const qilingzeSizes = {
      "1:1": "1024x1024",
      "16:9": "2048x1152",
      "9:16": "720x1280",
      "4:3": "1536x1152",
      "3:4": "1152x1536",
      "3:2": "1536x1024",
      "2:3": "1024x1536",
      "21:9": "1792x768",
    };
    return qilingzeSizes[aspectRatio] || "1024x1024";
  }

  if (provider === "geeknow") {
    const geeknowSizes = {
      "gpt-image-2": {
        "1:1": "1024x1024",
        "16:9": "1920x1080",
        "9:16": "1080x1920",
        "4:3": "1536x1152",
        "3:4": "1152x1536",
        "3:2": "1536x1024",
        "2:3": "1024x1536",
        "21:9": "1792x768",
      },
      "gpt-image-2-pro": {
        "1:1": "2048x2048",
        "16:9": "2048x1152",
        "9:16": "1152x2048",
        "4:3": "2048x1536",
        "3:4": "1536x2048",
        "3:2": "2560x1712",
        "2:3": "1712x2560",
        "21:9": "3024x1296",
      },
      "gpt-image-2-vip": {
        "1:1": "2048x2048",
        "16:9": "2560x1440",
        "9:16": "1440x2560",
        "4:3": "2304x1728",
        "3:4": "1728x2304",
        "3:2": "2496x1664",
        "2:3": "1664x2496",
        "21:9": "3024x1296",
      },
    };
    return geeknowSizes[model]?.[aspectRatio] || "1024x1024";
  }

  const modelSizes = {
    "gpt-image-2": {
      "9:16": "720x1280",
    },
  };

  const defaultSizes = {
    "1:1": "1024x1024",
    "16:9": "2048x1152",
    "9:16": "1152x2048",
    "4:3": "1536x1152",
    "3:4": "1152x1536",
    "3:2": "1536x1024",
    "2:3": "1024x1536",
    "21:9": "1792x768",
  };

  return modelSizes[model]?.[aspectRatio] || defaultSizes[aspectRatio] || "1024x1024";
};

const isGrsaiPixelModel = (model) => ["gpt-image-2-vip", "gpt-image-2.5-flare", "gpt-image-2.5-sunburst"].includes(model);

const getGrsaiQualityOptions = (model) => {
  if (model === "gpt-image-2-vip") return ["medium"];
  if (model === "gpt-image-2.5-flare") return ["medium", "low", "high"];
  if (model === "gpt-image-2.5-sunburst") return ["medium", "low", "high", "xhigh", "max"];
  return ["auto"];
};

const GEEKNOW_SUNBURST_MODEL = "gpt-image-2.5-sunburst";
const GEEKNOW_SUNBURST_SIZES = {
  "1K": { "1:1": "1024x1024", "4:3": "1536x1152", "3:2": "1536x1024", "2:3": "1024x1536", "16:9": "1920x1080", "9:16": "1080x1920" },
  "2K": { "1:1": "2048x2048", "4:3": "2048x1536", "3:2": "2560x1712", "2:3": "1712x2560", "16:9": "2048x1152", "9:16": "1152x2048" },
  "4K": { "1:1": "2880x2880", "4:3": "3840x2880", "3:2": "3840x2560", "2:3": "2560x3840", "16:9": "3840x2160", "9:16": "2160x3840" },
};
const getGeeknowSunburstSize = (aspectRatio, resolution) => {
  const size = GEEKNOW_SUNBURST_SIZES[resolution]?.[aspectRatio];
  if (!size) throw new Error("Geeknow Sunburst 不支持当前比例或分辨率，请重新选择。");
  return size;
};
const renderAspectRatioOptions = (select, provider, model) => {
  const ratios = provider === "fmgo" ? FMGO_ASPECT_RATIOS
    : provider === "geeknow" && model === GEEKNOW_SUNBURST_MODEL ? Object.keys(GEEKNOW_SUNBURST_SIZES["1K"]) : null;
  Array.from(select.options).forEach((option) => {
    const supported = !ratios || ratios.includes(option.value);
    option.disabled = !supported;
    option.hidden = !supported;
  });
  if (ratios && !ratios.includes(select.value)) select.value = "16:9";
};

const renderResolutionOptions = () => {
  if (!resolutionField || !resolutionSelect) return;
  const provider = getApiProvider();
  renderAspectRatioOptions(sizeSelect, provider, modelSelect.value);
  const isSupported = (provider === "qilingze" && modelSelect.value === QILINGZE_GPT25_MODEL)
    || (provider === "seventoken" && modelSelect.value === SEVENTOKEN_UPSCALE_MODEL)
    || (provider === "grsai" && isGrsaiPixelModel(modelSelect.value))
    || (provider === "fmgo" && FMGO_25_MODELS.includes(modelSelect.value))
    || (provider === "geeknow" && modelSelect.value === GEEKNOW_SUNBURST_MODEL)
    || provider === "lk888";
  resolutionField.hidden = !isSupported;
  resolutionField.closest(".model-row")?.classList.toggle("has-resolution", isSupported);
  if (!isSupported) return;

  const previous = resolutionSelect.value;
  const resolutions = ["1K", "2K", "4K"];
  resolutionSelect.replaceChildren(...resolutions.map((resolution) => {
    const option = document.createElement("option");
    option.value = resolution;
    option.textContent = resolution;
    return option;
  }));
  resolutionSelect.value = resolutions.includes(previous) ? previous : "1K";
};

const getModelDisplayName = (connectionId, model) => {
  if (connectionId === "seventoken" && model === SEVENTOKEN_UPSCALE_MODEL) return "GPT生图（超分）";
  if (connectionId === "lk888" && model === LK888_TT2_MODEL) return "TT Image 2";
  if (connectionId === "lk888" && model === LK888_TT25_MODEL) return "TT Image 2.5";
  return model;
};

const renderQualityOptions = (select, connectionId, model) => {
  if (!select) return;
  const previous = select.value;
  const values = connectionId === "grsai"
    ? getGrsaiQualityOptions(model)
    : connectionId === "geeknow" && model === GEEKNOW_SUNBURST_MODEL
      ? ["auto", "low", "medium", "high", "xhigh", "max"]
    : connectionId === "fmgo" && FMGO_25_MODELS.includes(model)
      ? ["auto"]
    : connectionId === "lk888" && model === LK888_TT25_MODEL
      ? ["auto", "low", "medium", "high", "xhigh", "max"]
      : ["auto", "medium", "high", "low"];
  const labels = {
    auto: "自动",
    high: "高清",
    low: "低清",
    max: "极致",
    medium: "中等",
    xhigh: "超高",
  };
  select.replaceChildren(...values.map((value) => {
