const tokenRegex = /图\d+/gu;

const getPromptTokens = () => promptInput.value.match(tokenRegex) || [];

const getTokenCounts = () => {
  const counts = new Map();
  getPromptTokens().forEach((token) => {
    counts.set(token, (counts.get(token) || 0) + 1);
  });
  return counts;
};

const getKnownTokens = () => {
  const known = new Set(references.map((ref) => ref.mention));
  return [...new Set(getPromptTokens().filter((token) => known.has(token)))];
};

const getUnknownTokens = () => {
  const known = new Set(references.map((ref) => ref.mention));
  return [...new Set(getPromptTokens().filter((token) => !known.has(token)))];
};

const getSelectedReferences = (mode = "auto") => {
  if (mode === "text") return [];

  const knownTokens = getKnownTokens();
  const mentionedRefs = knownTokens
    .map((token) => references.find((ref) => ref.mention === token))
    .filter(Boolean);

  return mentionedRefs;
};

const makeReferenceMention = (id) => `图${id}`;

const reindexReferences = () => {
  references.forEach((ref, index) => {
    const id = index + 1;
    ref.id = id;
    ref.mention = makeReferenceMention(id);
  });
};

const renderMentionBar = () => {
  const knownTokens = getKnownTokens();
  const unknownTokens = getUnknownTokens();

  if (!references.length) {
    mentionBar.textContent = "上传参考图后，可输入 @ 快捷插入 图1、图2、图3。";
    return;
  }

  if (!knownTokens.length && !unknownTokens.length) {
    const mode = referenceModeSelect?.value || "auto";
    const labels = {
      auto: "提示词未选择参考图，将按文生图处理",
      selected: "当前未选择参考图",
      text: "文生图：不使用参考图",
    };
    mentionBar.innerHTML = `<span class="chip">${labels[mode] || labels.auto}</span>`;
    return;
  }

  mentionBar.innerHTML = [
    ...knownTokens.map((token) => {
      const ref = references.find((item) => item.mention === token);
      return `
        <span class="chip bound">
          <img src="${ref.previewUrl}" alt="${escapeHtml(token)}" />
          ${escapeHtml(token)}
        </span>
      `;
    }),
    ...unknownTokens.map((token) => `<span class="chip missing">未识别 ${escapeHtml(token)}</span>`),
  ].join("");
};

const renderReferences = () => {
  referenceCount.textContent = `${references.length} 张`;
  if (clearReferencesButton) clearReferencesButton.disabled = references.length === 0;

  if (!references.length) {
    referenceList.innerHTML = '<div class="reference-empty">还没有参考图</div>';
    renderMentionBar();
    return;
  }

  const counts = getTokenCounts();
  referenceList.innerHTML = references.map((ref) => {
    const count = counts.get(ref.mention) || 0;
    const state = count ? `已选 ${count}次` : "未选";
    const status = ref.error ? "上传失败" : ref.publicUrl ? "已上传" : ref.uploading ? "上传中" : formatBytes(ref.file.size);
    return `
      <article class="reference-card ${count ? "is-mentioned" : ""} ${ref.error ? "is-missing-upload" : ""}" data-reference-id="${ref.id}">
        <img class="reference-thumb" src="${ref.previewUrl}" alt="${escapeHtml(ref.file.name)}" />
        <div class="reference-info">
          <button class="reference-token" type="button" data-insert-mention="${escapeHtml(ref.mention)}">${escapeHtml(ref.mention)}</button>
          <strong title="${escapeHtml(ref.file.name)}">${escapeHtml(ref.file.name)}</strong>
          <small>${escapeHtml(ref.file.type || "image")} · ${status}</small>
          <span class="reference-state">${state}</span>
        </div>
        <button class="icon-button remove-reference" type="button" data-remove-reference="${ref.id}" aria-label="移除 ${escapeHtml(ref.file.name)}">
          <svg viewBox="0 0 24 24"><path d="M6 6l12 12"/><path d="M18 6L6 18"/></svg>
        </button>
      </article>
    `;
  }).join("");
  renderMentionBar();
};

const insertPromptText = (text) => {
  const start = promptInput.selectionStart ?? promptInput.value.length;
  const end = promptInput.selectionEnd ?? promptInput.value.length;
  const before = promptInput.value.slice(0, start);
  const after = promptInput.value.slice(end);
  const prefix = before && !/\s$/.test(before) ? " " : "";
  const suffix = after && !/^\s/.test(after) ? " " : "";
  promptInput.value = `${before}${prefix}${text}${suffix}${after}`;
  const cursor = start + prefix.length + text.length + suffix.length;
  promptInput.focus();
  promptInput.setSelectionRange(cursor, cursor);
  closeMentionMenu();
  persistPromptDraft();
  renderReferences();
};

const addReferences = async (fileList) => {
  const slots = MAX_REFERENCES - references.length;
  const files = [...fileList]
    .filter((file) => file.type.startsWith("image/") || /\.(jpe?g|png|webp)$/i.test(file.name))
    .slice(0, Math.max(0, slots));

  if (!files.length) {
    setStatus(references.length >= MAX_REFERENCES ? `最多上传 ${MAX_REFERENCES} 张参考图。` : "请选择 JPG、PNG 或 WEBP 图片。");
    return;
  }

  files.forEach((file) => {
    references.push({
      error: "",
      file,
      id: 0,
      mention: "",
      previewUrl: URL.createObjectURL(file),
      publicUrl: "",
      uploadPromise: null,
      uploading: false,
    });
  });

  reindexReferences();
  imageInput.value = "";
  renderReferences();
  setStatus(`已加入 ${files.length} 张参考图。输入 @ 可快捷插入图1、图2、图3。`);
  try {
    await persistReferences();
  } catch (error) {
    setStatus(`图片已加入，但本地保存失败：${error?.message || error}`);
  }
};

const removeReference = async (id) => {
  const ref = references.find((item) => item.id === id);
  if (ref) URL.revokeObjectURL(ref.previewUrl);
  references = references.filter((item) => item.id !== id);
  reindexReferences();
  renderReferences();
  setStatus(ref ? `已移除 ${ref.mention}` : "已更新参考图。");
  try {
    await persistReferences();
  } catch (error) {
    setStatus(`参考图已移除，但本地记录更新失败：${error?.message || error}`);
  }
};

const clearAllReferences = async () => {
  if (!references.length) return;
  if (!window.confirm("确定清空全部参考图和本地保存记录吗？")) return;

  references.forEach((ref) => URL.revokeObjectURL(ref.previewUrl));
  references = [];
  imageInput.value = "";
  closeMentionMenu();
  renderReferences();

  try {
    await persistReferences();
    setStatus("已清空全部参考图和本地记录。");
  } catch (error) {
    setStatus(`参考图已清空，但本地记录清理失败：${error?.message || error}`);
  }
};

const getMentionQuery = () => {
  const cursor = promptInput.selectionStart ?? 0;
  const before = promptInput.value.slice(0, cursor);
  const at = before.lastIndexOf("@");
  if (at < 0) return null;
  const chunk = before.slice(at);
  if (/\s/.test(chunk)) return null;
  return {
    end: cursor,
    query: chunk.slice(1).toLowerCase(),
    start: at,
  };
};

const closeMentionMenu = () => {
  mentionMenu.hidden = true;
  mentionMenu.innerHTML = "";
  mentionState = { activeIndex: 0, end: 0, items: [], open: false, start: 0 };
};

const renderMentionMenu = () => {
  if (!mentionState.items.length) {
    mentionMenu.hidden = false;
    mentionMenu.innerHTML = `
      <div class="mention-title">选择当前上传的参考图</div>
      <div class="mention-title">暂无可选参考图</div>
    `;
    mentionState.open = false;
    return;
  }

  mentionMenu.hidden = false;
  mentionMenu.innerHTML = `
    <div class="mention-title">选择当前上传的参考图</div>
    ${mentionState.items.map((ref, index) => `
      <button class="mention-option ${index === mentionState.activeIndex ? "is-active" : ""}" type="button" data-mention-id="${ref.id}">
        <img src="${ref.previewUrl}" alt="${escapeHtml(ref.mention)}" />
        <span>
          <strong>${escapeHtml(ref.mention)}</strong>
          <small>${escapeHtml(ref.file.name)}</small>
        </span>
        <em class="mention-badge">${getTokenCounts().get(ref.mention) ? "已选" : "未选"}</em>
      </button>
    `).join("")}
  `;
};

const updateMentionMenu = () => {
  const mention = getMentionQuery();
  if (!mention) {
    closeMentionMenu();
    return;
  }

  const query = mention.query;
  const filtered = references.filter((ref) =>
    `${ref.mention} ${ref.file.name}`.toLowerCase().includes(query),
  );

  mentionState = {
    activeIndex: 0,
    end: mention.end,
    items: filtered.length ? filtered : references,
    open: references.length > 0,
    start: mention.start,
  };
  renderMentionMenu();
};

const chooseMention = (ref) => {
  const before = promptInput.value.slice(0, mentionState.start);
  const after = promptInput.value.slice(mentionState.end);
  const suffix = after && !/^\s/.test(after) ? " " : "";
  promptInput.value = `${before}${ref.mention}${suffix}${after}`;
  const cursor = before.length + ref.mention.length + suffix.length;
  promptInput.focus();
  promptInput.setSelectionRange(cursor, cursor);
  closeMentionMenu();
  persistPromptDraft();
  renderReferences();
  setStatus(`${ref.mention} 已写入提示词。`);
};

const fetchJson = async (url, options = {}, timeoutMs = 60000) => {
  const controller = new AbortController();
  const timeout = window.setTimeout(() => controller.abort(), timeoutMs);
  try {
    const response = await fetch(url, { ...options, signal: controller.signal });
    const contentType = response.headers.get("content-type") || "";
    const body = contentType.includes("application/json")
      ? await response.json()
      : await response.text();

    if (!response.ok) {
      const message = typeof body === "string"
        ? body
        : (typeof body?.error === "string" ? body.error : body?.error?.message)
          || body?.message || `HTTP ${response.status}`;
      const error = new Error(message);
      error.status = response.status;
      throw error;
    }

    return body;
  } finally {
    window.clearTimeout(timeout);
  }
};

const uploadReference = async (ref, apiKey, onProgress, endpoint = "") => {
  if (ref.publicUrl) return ref.publicUrl;

  ref.uploading = true;
  ref.error = "";
  renderReferences();
  onProgress?.(`正在申请上传地址：${ref.mention}`);

  const contentType = ref.file.type || "image/png";
  const presign = await fetchJson(apiUrl("/api/upload/presign", endpoint), {
    method: "POST",
    headers: {
      Accept: "application/json",
      Authorization: `Bearer ${apiKey}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({
      content_type: contentType,
      filename: ref.file.name,
      size: ref.file.size,
    }),
  });

  const data = presign?.data || presign;
  const uploadUrl = data?.upload_url;
  const publicUrl = data?.public_url;
  if (!uploadUrl || !publicUrl) {
    throw new Error("上传接口没有返回 upload_url 或 public_url。");
  }

  onProgress?.(`正在上传参考图：${ref.mention}`);
  const putResponse = await fetch(uploadUrl, {
    method: "PUT",
    headers: { "Content-Type": contentType },
    body: ref.file,
  });

  if (!putResponse.ok) {
    throw new Error(`参考图上传失败：HTTP ${putResponse.status}`);
  }

  ref.publicUrl = publicUrl;
  ref.uploading = false;
  renderReferences();
  return publicUrl;
};

