const getImageBlob = async (url, headers = {}, timeoutMs = IMAGE_FETCH_TIMEOUT_MS) => {
  const controller = new AbortController();
  const timeout = window.setTimeout(() => controller.abort(), timeoutMs);
  try {
    const response = await fetch(url, { cache: "no-store", headers, signal: controller.signal });
    if (!response.ok) {
      const error = new Error(`读取生成图片失败：HTTP ${response.status}`);
      error.status = response.status;
      throw error;
    }
    const blob = await response.blob();
    if (!blob.size) throw new Error("生成图片内容为空。");
    return blob;
  } finally {
    window.clearTimeout(timeout);
  }
};

const getGeneratedImageBlob = async (url, apiKey = "") => {
  const canRetryWithAuthorization = /^https?:\/\//i.test(String(url || "")) && apiKey;
  let lastError = null;
  for (let round = 0; round < 3; round += 1) {
    try {
      return await getImageBlob(url);
    } catch (error) {
      lastError = error;
      const shouldTryAuthorization = canRetryWithAuthorization
        && (round === 0 || [401, 403].includes(error?.status))
        && error?.name !== "AbortError";
      if (shouldTryAuthorization) {
        try {
          return await getImageBlob(url, { Authorization: `Bearer ${apiKey}` });
        } catch (authorizedError) {
          lastError = authorizedError;
        }
      }
    }
    if (round < 2) await sleep(800 * (round + 1));
  }
  throw new Error(`图片已经生成，但未能回收到本地：${lastError?.message || "图片地址不可读取"}。请关闭当前页面，双击“启动生图工作台.bat”重新打开后再生成。`);
};

const releaseBatchResultObjectUrl = (result) => {
  if (result?.blob instanceof Blob && result.objectUrl) URL.revokeObjectURL(result.objectUrl);
};

const releaseBatchJobResults = (job) => {
  (job?.results || []).forEach(releaseBatchResultObjectUrl);
};

const serializeBatchResults = (job) => (job.results || []).map((result) => ({
  blob: result.blob,
  createdAt: result.createdAt || 0,
  favoriteId: result.favoriteId || "",
  options: result.options || null,
  prompt: result.prompt || "",
  sourceUrl: result.sourceUrl || "",
}));

const restoreBatchResults = (record) => {
  const stored = Array.isArray(record.results)
    ? record.results
    : record.resultBlob instanceof Blob
      ? [{ blob: record.resultBlob, sourceUrl: record.resultSourceUrl || "", favoriteId: record.favoriteId || "", prompt: record.lastPrompt || "", options: record.lastOptions || null }]
      : [];
  return stored.filter((result) => result?.blob instanceof Blob).map((result) => ({
    ...result,
    objectUrl: URL.createObjectURL(result.blob),
  }));
};

const readFileAsDataUrl = (file) => new Promise((resolve, reject) => {
  const reader = new FileReader();
  reader.onload = () => resolve(String(reader.result || ""));
  reader.onerror = () => reject(reader.error || new Error(`无法读取 ${file.name}`));
  reader.readAsDataURL(file);
});

const readFileAsBase64 = async (file) => {
  const dataUrl = await readFileAsDataUrl(file);
  return dataUrl.includes(",") ? dataUrl.slice(dataUrl.indexOf(",") + 1) : dataUrl;
};

const saveFavoriteImage = async (image) => {
  const blob = image.blob || await getImageBlob(image.url);
  const database = await openReferenceDatabase();
  const transaction = database.transaction(FAVORITE_DB_STORE, "readwrite");
  const id = window.crypto?.randomUUID?.() || `favorite-${Date.now()}-${Math.random().toString(16).slice(2)}`;
  const record = {
    blob,
    createdAt: Date.now(),
    filename: image.filename,
    id,
    model: image.model,
    prompt: image.prompt,
    size: image.size,
    title: image.title,
    type: blob.type || "image/png",
  };
  transaction.objectStore(FAVORITE_DB_STORE).put(record);
  await waitForTransaction(transaction);
  return record;
};

