const extractTaskId = (body) =>
  body?.task_id || body?.id || body?.task?.id || body?.data?.task_id || body?.data?.id || "";

const extractStatus = (body) =>
  String(body?.state || body?.data?.state || body?.task?.state
    || body?.status || body?.task?.status || body?.data?.status || "").toLowerCase();

const extractProgress = (body) => {
  const value = body?.progress ?? body?.task?.progress ?? body?.data?.progress;
  return value == null ? "" : String(value);
};

const extractRemoteError = (body, fallback) => {
  const error = body?.error ?? body?.data?.error ?? body?.task?.error;
  if (typeof error === "string" && error.trim()) return error.trim();
  return error?.message || body?.message || body?.msg || fallback;
};

const extractImageFromContent = (content) => {
  if (!content) return "";
  if (Array.isArray(content)) {
    return content.map(extractImageFromContent).find(Boolean) || "";
  }
  if (typeof content === "object") {
    const nestedCandidates = [
      content.result_url,
      content.url,
      content.image_url?.url,
      typeof content.image_url === "string" ? content.image_url : "",
      content.b64_json ? `data:image/png;base64,${content.b64_json}` : "",
      content.images,
      content.data,
      content.result,
      content.output,
      content.text,
      content.content,
    ];
    return nestedCandidates.map(extractImageFromContent).find(Boolean) || "";
  }

  const value = String(content).trim();
  if (!value) return "";
  if (/^data:image\/[a-z0-9.+-]+;base64,/i.test(value)) return value;
  if (/^https?:\/\/\S+$/i.test(value)) return value;

  if ((value.startsWith("{") && value.endsWith("}")) || (value.startsWith("[") && value.endsWith("]"))) {
    try {
      const parsedImage = extractImageFromContent(JSON.parse(value));
      if (parsedImage) return parsedImage;
    } catch {
      // Continue with text extraction when content is not valid JSON.
    }
  }

  const markdownMatch = value.match(/!\[[^\]]*\]\((data:image\/[^)]+|https?:\/\/[^)\s]+)\)/i);
  if (markdownMatch?.[1]) return markdownMatch[1];
  const htmlMatch = value.match(/<img[^>]+src=["'](data:image\/[^"']+|https?:\/\/[^"']+)["']/i);
  if (htmlMatch?.[1]) return htmlMatch[1];
  const dataUrlMatch = value.match(/data:image\/[a-z0-9.+-]+;base64,[a-z0-9+/=\r\n]+/i);
  if (dataUrlMatch?.[0]) return dataUrlMatch[0].replace(/\s+/g, "");
  const urlMatch = value.match(/https?:\/\/[^\s"'<>\])}]+/i);
  if (urlMatch?.[0]) return urlMatch[0];
  const compact = value.replace(/\s+/g, "");
  if (compact.length > 512 && /^[a-z0-9+/]+=*$/i.test(compact)) {
    return `data:image/png;base64,${compact}`;
  }
  return "";
};

const extractImageUrl = (body) => {
  const first = Array.isArray(body?.data) ? body.data[0] : null;
  const resultFirst = Array.isArray(body?.result?.data) ? body.result.data[0] : null;
  const resultChoiceContent = body?.result?.choices?.[0]?.message?.content;
  const choiceContent = body?.choices?.[0]?.message?.content;
  const candidates = [
    first?.url,
    first?.b64_json ? `data:image/png;base64,${first.b64_json}` : "",
    resultFirst?.url,
    resultFirst?.b64_json ? `data:image/png;base64,${resultFirst.b64_json}` : "",
    body?.result_url,
    body?.results?.[0]?.url,
    body?.url,
    body?.image_url,
    body?.b64_json ? `data:image/png;base64,${body.b64_json}` : "",
    body?.data?.url,
    body?.data?.b64_json ? `data:image/png;base64,${body.data.b64_json}` : "",
    Array.isArray(body?.images) ? body.images[0]?.url : "",
    Array.isArray(body?.images) && body.images[0]?.b64_json ? `data:image/png;base64,${body.images[0].b64_json}` : "",
    extractImageFromContent(body?.data),
    extractImageFromContent(body?.result),
    extractImageFromContent(resultChoiceContent),
    extractImageFromContent(choiceContent),
    extractImageFromContent(body?.result?.output),
    extractImageFromContent(body?.output),
  ];
  return candidates.map(extractImageFromContent).find(Boolean) || "";
};

const getPollDelay = (body) => {
  const rawDelay = Number(body?.poll_after_ms ?? body?.task?.poll_after_ms ?? body?.data?.poll_after_ms);
  return Number.isFinite(rawDelay) ? Math.min(15000, Math.max(1000, rawDelay)) : POLL_INTERVAL_MS;
};

const getPollUrl = (body, remoteTaskId, provider, endpoint = "") => {
  const statusUrl = body?.task?.status_url || body?.status_url || body?.poll_url || body?.data?.poll_url || "";
  if (statusUrl) {
    if (/^https?:\/\//i.test(statusUrl)) return statusUrl;
    return new URL(statusUrl, endpoint || getEndpoint()).href;
  }
  if (provider === "fmgo") return apiUrl(`/v1/tasks/${encodeURIComponent(remoteTaskId)}`, endpoint);
  if (provider === "seventoken") return apiUrl(`/v1/images/tasks/${encodeURIComponent(remoteTaskId)}`, endpoint);
  if (provider === "qilingze") return apiUrl(`/v1/images/generations/${encodeURIComponent(remoteTaskId)}`, endpoint);
  if (provider === "grsai") {
    const url = new URL(apiUrl("/v1/api/result", endpoint));
    url.searchParams.set("id", remoteTaskId);
    return url.href;
  }
  if (provider === "lk888") {
    const url = new URL(apiUrl("/v1/media/status", endpoint));
    url.searchParams.set("task_id", remoteTaskId);
    return url.href;
  }
  return apiUrl(`/v1/images/generations/async/${encodeURIComponent(remoteTaskId)}`, endpoint);
};

const getFreshPollUrl = (url, provider) => {
  if (provider !== "fmgo") return url;
  const freshUrl = new URL(url);
  freshUrl.searchParams.set("_poll", `${Date.now()}-${Math.random().toString(16).slice(2)}`);
  return freshUrl.href;
};

const getSevenTokenTaskImage = async (remoteTaskId, apiKey, endpoint) => {
  const contentUrl = apiUrl(`/v1/images/tasks/${encodeURIComponent(remoteTaskId)}/content/0`, endpoint);
  const blob = await getImageBlob(contentUrl, {
    Accept: "image/*",
    Authorization: `Bearer ${apiKey}`,
  });
  return readFileAsDataUrl(blob);
};

const waitForImage = async (initialBody, apiKey, taskCard, options) => {
  let body = initialBody;
  let remoteTaskId = extractTaskId(body);
  const startedAt = Date.now();
  const provider = options?.provider || getApiProvider();
  let completedWithoutImage = 0;
  let pollFailureCount = 0;

  const publishRemoteTask = () => {
    if (!remoteTaskId) return;
    taskCard.onRemoteTask?.({
      pollUrl: getPollUrl(body, remoteTaskId, provider, options?.endpoint || ""),
      taskId: remoteTaskId,
    });
  };
  publishRemoteTask();

  while (Date.now() - startedAt < MAX_POLL_MS) {
    const status = extractStatus(body);
    const progress = extractProgress(body);
    if (["failed", "failure", "error", "violation", "cancelled", "canceled", "rejected"].includes(status)) {
      const terminalError = new Error(extractRemoteError(body, `任务失败：${status}`));
      terminalError.isRemoteTerminalFailure = true;
      throw terminalError;
    }

    const isComplete = ["completed", "succeeded", "success", "finished", "done"].includes(status);
    if (provider === "seventoken" && isComplete) {
      remoteTaskId = remoteTaskId || extractTaskId(body);
      if (!remoteTaskId) throw new Error("Token超市任务已完成，但响应中没有 task_id。");
      try {
        return await getSevenTokenTaskImage(remoteTaskId, apiKey, options?.endpoint || "");
      } catch (error) {
        const fallbackImageUrl = extractImageUrl(body);
        if (fallbackImageUrl) return fallbackImageUrl;
        throw new Error(`Token超市任务已完成，但图片下载失败：${error?.message || error}`);
      }
    }

    const imageUrl = extractImageUrl(body);
    if (imageUrl) return imageUrl;

    if (isComplete) {
      completedWithoutImage += 1;
      const completedRetryLimit = provider === "fmgo" ? 20 : 3;
      if (completedWithoutImage >= completedRetryLimit) {
        const providerName = provider === "qilingze"
          ? "麒麟泽"
          : provider === "fmgo"
            ? "FMGO"
            : provider === "lk888"
              ? "长风AI"
              : "当前接口";
        throw new Error(`${providerName}任务已经完成，但状态响应中没有可识别的图片 URL 或 Base64。请把该任务的查询响应发给我继续适配。`);
      }
    } else {
      completedWithoutImage = 0;
    }

    remoteTaskId = remoteTaskId || extractTaskId(body);
    if (!remoteTaskId) {
      throw new Error("异步接口没有返回 task_id。");
    }
    publishRemoteTask();

    updateTaskVisual(taskCard, "等待完成", `${remoteTaskId} · ${status || "queued"} ${progress}`);
    await sleep(getPollDelay(body));

    const pollUrl = getPollUrl(body, remoteTaskId, provider, options?.endpoint || "");
    if (!pollUrl) {
      throw new Error("接口返回了任务编号，但没有返回可用的轮询地址。");
    }

    try {
      body = await fetchJson(getFreshPollUrl(pollUrl, provider), {
        method: "GET",
        cache: "no-store",
        headers: {
          Accept: "application/json",
          Authorization: `Bearer ${apiKey}`,
        },
      }, provider === "fmgo" ? FMGO_POLL_REQUEST_TIMEOUT_MS : 60000);
      pollFailureCount = 0;
    } catch (error) {
      if (provider !== "fmgo" || [401, 403].includes(error?.status)) throw error;
      pollFailureCount += 1;
      updateTaskVisual(taskCard, "重新查询状态", `${remoteTaskId} · 第 ${pollFailureCount} 次查询超时或被代理中断，正在重试`);
      await sleep(Math.min(1000 * pollFailureCount, 5000));
    }
  }

  throw new Error(`任务超过 ${Math.round(MAX_POLL_MS / 60000)} 分钟仍未完成。`);
};

const finishTask = async (task, imageUrl, apiKey) => {
  const filename = `reference-atelier-${task.id}-${Date.now()}.png`;
  updateTaskVisual(task, "保存结果", "正在把生成图片保存到浏览器本地");

  const blob = await getGeneratedImageBlob(imageUrl, apiKey);
  const localUrl = URL.createObjectURL(blob);

  task.card.classList.remove("is-running", "is-error");
  task.card.classList.add("is-complete");
  task.visual.innerHTML = `
    <img src="${localUrl}" alt="任务 #${task.id} 生成结果" />
  `;
  setTaskMediaActionsVisible(task, true);
  task.editButton.disabled = false;
  finishedImages.set(String(task.id), {
    blob,
    filename,
    model: task.model,
    objectUrl: localUrl,
    prompt: task.prompt,
    size: task.size,
    title: `任务 #${task.id} 生成结果`,
    url: localUrl,
  });
};

const failTask = (task, message) => {
  task.card.classList.remove("is-running");
  task.card.classList.add("is-error");
  task.visual.innerHTML = `
    <div class="placeholder">
      <strong>生成失败</strong>
      <small>${escapeHtml(message)}</small>
    </div>
  `;
  setTaskMediaActionsVisible(task, false);
  task.editButton.disabled = false;
};

const prepareTaskForRun = (task, isReplacement = false) => {
  const previousImage = finishedImages.get(String(task.id));
  if (previousImage?.objectUrl) URL.revokeObjectURL(previousImage.objectUrl);
  finishedImages.delete(String(task.id));

  task.card.classList.remove("is-complete", "is-error");
  task.card.classList.add("is-running");
  setTaskMediaActionsVisible(task, false);
  task.editButton.disabled = true;
  if (task.favoriteButton) {
    task.favoriteButton.disabled = false;
    task.favoriteButton.textContent = "收藏";
  }
  updateTaskVisual(task, "生成中", isReplacement ? `任务 #${task.id} 正在覆盖生成` : `任务 #${task.id} 准备提交`);
};

const submitGeneration = async (apiKey, taskCard, prompt, selectedRefs, options) => {
  if (options.provider === "grsai") {
    const images = await Promise.all(selectedRefs.map((ref) => readFileAsDataUrl(ref.file)));
    const payload = {
      model: options.model,
      prompt,
      images,
      aspectRatio: options.size,
      quality: options.quality,
      replyType: "async",
    };
    setTaskRoute(taskCard, `Grsai /v1/api/generate · 异步任务 · model=${options.model} · ${options.size}`, selectedRefs.length);
    updateTaskVisual(taskCard, "提交异步任务", `Grsai · ${options.model} · ${options.size}`);
    const body = await fetchJson(apiUrl("/v1/api/generate", options.endpoint), {
      method: "POST",
      headers: {
        Accept: "application/json",
        Authorization: `Bearer ${apiKey}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify(payload),
    }, 60000);
    if (["failed", "violation"].includes(extractStatus(body))) {
      throw new Error(extractRemoteError(body, "Grsai 生成失败。"));
    }
    const imageUrl = extractImageUrl(body);
    if (imageUrl && !extractTaskId(body)) return imageUrl;
    if (extractTaskId(body)) return waitForImage(body, apiKey, taskCard, options);
    throw new Error("Grsai 接口没有返回任务编号或图片地址。");
  }

  if (options.provider === "lk888") {
    const referenceLimit = getLk888ReferenceLimit(options.model);
    if (selectedRefs.length > referenceLimit) {
      throw new Error(`${options.model} 最多支持 ${referenceLimit} 张参考图。`);
    }
    const payload = await buildLk888Payload({
      aspectRatio: options.aspectRatio,
      model: options.model,
      prompt,
      quality: options.quality,
      references: selectedRefs,
      resolution: options.resolution,
      size: options.size,
    });
    setTaskRoute(taskCard, `长风AI /v1/media/generate · 异步任务 · model=${options.model}`, selectedRefs.length);
    updateTaskVisual(taskCard, "提交异步任务", `长风AI · ${options.model} · ${options.aspectRatio} · ${options.resolution}`);
    const body = await fetchJson(apiUrl("/v1/media/generate", options.endpoint), {
      method: "POST",
      headers: {
        Accept: "application/json",
        Authorization: `Bearer ${apiKey}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify(payload),
    }, 60000);
    const imageUrl = extractImageUrl(body);
    if (imageUrl && !extractTaskId(body)) return imageUrl;
    if (extractTaskId(body)) return waitForImage(body, apiKey, taskCard, options);
    throw new Error("长风AI异步接口没有返回 task_id 或图片数据。");
  }

  if (options.provider === "seventoken") {
    let body;
    if (selectedRefs.length) {
      const formData = new FormData();
      formData.append("model", SEVENTOKEN_UPSCALE_MODEL);
      formData.append("prompt", buildPromptForApi(prompt, selectedRefs));
      formData.append("size", options.size);
      formData.append("n", "1");
      formData.append("response_format", "url");
      if (options.quality !== "auto") formData.append("quality", options.quality);
      selectedRefs.forEach((ref) => formData.append("image[]", ref.file, ref.file.name));

      setTaskRoute(taskCard, `Token超市 /v1/images/edits/async · ${options.size} · model=${SEVENTOKEN_UPSCALE_MODEL}`, selectedRefs.length);
      updateTaskVisual(taskCard, "提交异步任务", `Token超市 · GPT生图（超分）· ${options.resolution}`);
      body = await fetchJson(apiUrl("/v1/images/edits/async", options.endpoint), {
        method: "POST",
        headers: {
          Accept: "application/json",
          Authorization: `Bearer ${apiKey}`,
        },
        body: formData,
      }, 60000);
    } else {
      const payload = {
        model: SEVENTOKEN_UPSCALE_MODEL,
        prompt,
        size: options.size,
        n: 1,
        response_format: "url",
      };
      if (options.quality !== "auto") payload.quality = options.quality;

      setTaskRoute(taskCard, `Token超市 /v1/images/generations/async · ${options.size} · model=${SEVENTOKEN_UPSCALE_MODEL}`, 0);
      updateTaskVisual(taskCard, "提交异步任务", `Token超市 · GPT生图（超分）· ${options.resolution}`);
      body = await fetchJson(apiUrl("/v1/images/generations/async", options.endpoint), {
        method: "POST",
        headers: {
          Accept: "application/json",
          Authorization: `Bearer ${apiKey}`,
          "Content-Type": "application/json",
        },
        body: JSON.stringify(payload),
      }, 60000);
    }

    const imageUrl = extractImageUrl(body);
    if (imageUrl && !extractTaskId(body)) return imageUrl;
    if (extractTaskId(body)) return waitForImage(body, apiKey, taskCard, options);
    throw new Error("Token超市异步接口没有返回 task_id 或图片数据。");
  }

  if (options.provider === "qilingze") {
    if (options.model === "gpt-image-2") {
      const imageUrls = await Promise.all(selectedRefs.map((ref) => readFileAsDataUrl(ref.file)));
      const payload = buildQilingzeGpt2Payload({
        imageUrls,
        prompt,
        size: options.size,
      });
      setTaskRoute(taskCard, `麒麟泽 /v1/images/generations · 异步请求 · model=${options.model}`, selectedRefs.length);
      updateTaskVisual(taskCard, selectedRefs.length ? "提交异步参考生图" : "提交异步文生图", `麒麟泽 · ${options.model} · ${options.aspectRatio}`);
      const body = await fetchJson(apiUrl("/v1/images/generations", options.endpoint), {
        method: "POST",
        headers: {
          Accept: "application/json",
          Authorization: `Bearer ${apiKey}`,
          "Content-Type": "application/json",
        },
        body: JSON.stringify(payload),
      }, 60000);
      const imageUrl = extractImageUrl(body);
      if (imageUrl && !extractTaskId(body)) return imageUrl;
      if (extractTaskId(body)) return waitForImage(body, apiKey, taskCard, options);
      throw new Error("麒麟泽 gpt-image-2 异步接口没有返回 task_id 或图片数据。");
    }

    if (options.model === QILINGZE_GPT25_MODEL && !selectedRefs.length) {
      const payload = buildQilingzeGpt25Payload({
        model: options.model,
        prompt,
        size: options.size,
      });
      setTaskRoute(taskCard, `麒麟泽 /v1/images/generations · 同步请求 · ${options.size} · model=${options.model}`, 0);
      updateTaskVisual(taskCard, "生成中", `麒麟泽 · ${options.model} · ${options.aspectRatio} · ${options.resolution}`);
      const officialBody = await fetchJson(apiUrl("/v1/images/generations", options.endpoint), {
        method: "POST",
        headers: {
          Accept: "application/json",
          Authorization: `Bearer ${apiKey}`,
          "Content-Type": "application/json",
        },
        body: JSON.stringify(payload),
      }, MAX_POLL_MS);
      const officialImageUrl = extractImageUrl(officialBody);
      if (officialImageUrl) return officialImageUrl;
      if (extractTaskId(officialBody)) return waitForImage(officialBody, apiKey, taskCard, options);
      throw new Error("麒麟泽 GPT Image 2.5 接口没有返回图片地址或图片数据。");
    }

    if (options.model === "nano-banana-2") {
      const urls = await Promise.all(selectedRefs.map((ref) => readFileAsDataUrl(ref.file)));
      const imageSize = "1K";
      const payload = buildQilingzeNanoPayload({
        aspectRatio: options.aspectRatio,
        imageSize,
        model: options.model,
        prompt,
        urls,
      });
      setTaskRoute(taskCard, `麒麟泽 /v1/images/generations · 官方格式 · ${options.aspectRatio} · ${imageSize} · model=${options.model}`, selectedRefs.length);
      updateTaskVisual(taskCard, "生成中", `麒麟泽 · ${options.model} · ${options.aspectRatio} · ${imageSize}`);
      const officialBody = await fetchJson(apiUrl("/v1/images/generations", options.endpoint), {
        method: "POST",
        headers: {
          Accept: "application/json",
          Authorization: `Bearer ${apiKey}`,
          "Content-Type": "application/json",
        },
        body: JSON.stringify(payload),
      }, MAX_POLL_MS);
      const officialImageUrl = extractImageUrl(officialBody);
      if (officialImageUrl) return officialImageUrl;
      if (extractTaskId(officialBody)) return waitForImage(officialBody, apiKey, taskCard, options);
      throw new Error("麒麟泽官方接口没有返回图片地址。");
    }

    let body;
    const asyncHeaders = {
      Accept: "application/json",
      Authorization: `Bearer ${apiKey}`,
      Prefer: "respond-async",
      "X-Flow-Async": "1",
    };

    if (selectedRefs.length) {
      const formData = new FormData();
      formData.append("model", options.model);
      formData.append("prompt", buildPromptForApi(prompt, selectedRefs));
      formData.append("size", options.size);
      if (options.model !== QILINGZE_GPT25_MODEL) {
        formData.append("response_format", "b64_json");
      }
      if (options.model !== QILINGZE_GPT25_MODEL && options.quality !== "auto") {
        formData.append("quality", options.quality);
      }
      selectedRefs.forEach((ref) => {
        formData.append(options.model === QILINGZE_GPT25_MODEL ? "image[]" : "image", ref.file, ref.file.name);
      });
      setTaskRoute(taskCard, `麒麟泽 /v1/images/edits · 同步文件上传 · model=${options.model}`, selectedRefs.length);
      updateTaskVisual(taskCard, "参考图生成中", `麒麟泽同步上传 ${selectedRefs.length} 张参考图`);
      body = await fetchJson(apiUrl("/v1/images/edits", options.endpoint), {
        method: "POST",
        headers: {
          Accept: "application/json",
          Authorization: `Bearer ${apiKey}`,
        },
        body: formData,
      }, MAX_POLL_MS);
    } else {
      const payload = {
        model: options.model,
        n: 1,
        prompt,
        response_format: "b64_json",
        size: options.size,
      };
      if (options.quality !== "auto") {
        payload.quality = options.quality;
      }

      setTaskRoute(taskCard, `麒麟泽 /v1/images/generations · 异步请求 · model=${options.model}`, 0);
      updateTaskVisual(taskCard, "异步生成中", `麒麟泽 · ${options.model} · 可继续创建其他任务`);
      body = await fetchJson(apiUrl("/v1/images/generations", options.endpoint), {
        method: "POST",
        headers: {
          ...asyncHeaders,
          "Content-Type": "application/json",
        },
        body: JSON.stringify(payload),
      }, MAX_POLL_MS);
    }

    const imageUrl = extractImageUrl(body);
    if (imageUrl) return imageUrl;
    if (extractTaskId(body)) return waitForImage(body, apiKey, taskCard, options);
    throw new Error("麒麟泽接口没有返回图片地址或异步任务编号。");
  }

  if (options.provider === "fmgo") {
    let body;
    if (selectedRefs.length) {
      const formData = new FormData();
      formData.append("model", options.model);
      formData.append("prompt", buildFmgoPrompt(prompt, options.aspectRatio));
      formData.append("aspect_ratio", options.aspectRatio);
      formData.append("image_size", getFmgoImageSize(options.model, options.resolution));
      selectedRefs.forEach((ref) => {
        formData.append("image", ref.file, ref.file.name);
      });
      setTaskRoute(taskCard, `FMGO /v1/images/edits · 原生 ${options.aspectRatio}`, selectedRefs.length);
      updateTaskVisual(taskCard, "提交任务", `FMGO 多图参考 · ${selectedRefs.length} 张`);
      body = await fetchJson(apiUrl("/v1/images/edits", options.endpoint), {
        method: "POST",
        headers: {
          Accept: "application/json",
          Authorization: `Bearer ${apiKey}`,
          Prefer: "respond-async",
          "X-Flow-Async": "1",
        },
        body: formData,
      }, 90000);
    } else {
      const payload = {
        aspect_ratio: options.aspectRatio,
        image_size: getFmgoImageSize(options.model, options.resolution),
        model: options.model,
        prompt: buildFmgoPrompt(prompt, options.aspectRatio),
      };

      setTaskRoute(taskCard, `FMGO /v1/images/generations · ${getFmgoImageSize(options.model, options.resolution)} · 异步轮询`, 0);
      updateTaskVisual(taskCard, "提交任务", "FMGO 文生图");
      body = await fetchJson(apiUrl("/v1/images/generations", options.endpoint), {
        method: "POST",
        headers: {
          Accept: "application/json",
          Authorization: `Bearer ${apiKey}`,
          "Content-Type": "application/json",
          Prefer: "respond-async",
          "X-Flow-Async": "1",
        },
        body: JSON.stringify(payload),
      }, 90000);
    }

    return waitForImage(body, apiKey, taskCard, options);
  }

  const referenceImages = await Promise.all(selectedRefs.map((ref) => readFileAsBase64(ref.file)));
  const requestSize = options.model === GEEKNOW_SUNBURST_MODEL
    ? getGeeknowSunburstSize(options.aspectRatio, options.resolution || "1K") : options.size;
  if (options.model === GEEKNOW_SUNBURST_MODEL && !["auto", "low", "medium", "high", "xhigh", "max"].includes(options.quality)) {
    throw new Error("Geeknow Sunburst 的质量参数无效，请重新选择。");
  }
  const payload = {
    model: options.model,
    n: 1,
    prompt: buildPromptForApi(prompt, selectedRefs),
    response_format: "b64_json",
    size: requestSize,
  };

  if (options.quality !== "auto") {
    payload.quality = options.quality;
  }

  if (referenceImages.length) payload.image = referenceImages;

  setTaskRoute(taskCard, `Geeknow /v1/images/generations · 同步生成 · ${requestSize} · quality=${options.quality}`, selectedRefs.length);
  updateTaskVisual(taskCard, "生成中", selectedRefs.length ? `正在读取 ${selectedRefs.length} 张参考图` : `官网尺寸 ${requestSize}`);
  const body = await fetchJson(apiUrl("/v1/images/generations", options.endpoint), {
    method: "POST",
    headers: {
      Accept: "application/json",
      Authorization: `Bearer ${apiKey}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify(payload),
  }, MAX_POLL_MS);

  const imageUrl = extractImageUrl(body);
  if (imageUrl) return imageUrl;
  if (extractTaskId(body)) return waitForImage(body, apiKey, taskCard, options);
  throw new Error("Geeknow 官方接口没有返回图片或异步任务编号。");
};

const classifyError = (error) => {
  const message = error?.message || String(error);
  const lower = message.toLowerCase();
  if (error?.name === "AbortError") return "请求超时，请稍后重试。";
  if (lower.includes("failed to fetch") || lower.includes("network")) {
    return "浏览器无法连接或读取当前接口响应。请用“启动生图工作台.bat”打开，并确认网络能访问所选接口及其图片存储域名。";
  }
  if (lower.includes("401") || lower.includes("403") || lower.includes("unauthorized")) return "API KEY 无效或没有权限。";
  if (lower.includes("quota") || lower.includes("billing") || lower.includes("余额") || lower.includes("额度")) return `额度或余额问题：${message}`;
  if (lower.includes("rate") || lower.includes("429")) return `请求过快：${message}`;
  return message;
};

const executeTask = async (task, apiKey, isReplacement = false) => {
  prepareTaskForRun(task, isReplacement);
  setStatus(isReplacement
    ? `任务 #${task.id} 已更新提示词，正在原位置覆盖生成。`
    : `任务 #${task.id} 已创建，可继续点击生成图像。`);

  try {
    const imageUrl = await submitGeneration(apiKey, task, task.prompt, task.selectedRefs, task.options);
    await finishTask(task, imageUrl, apiKey);
    setStatus(`任务 #${task.id} 已${isReplacement ? "覆盖生成" : "完成"}。`);
  } catch (error) {
    const message = classifyError(error);
    failTask(task, message);
    setStatus(`任务 #${task.id} 失败：${message}`);
  } finally {
    renderReferences();
  }
};

const handleGenerate = async () => {
  const connection = getActiveConnection();
  const apiKey = getApiKey();
  const prompt = promptInput.value.trim();

  if (!connection?.endpoint || !apiKey) {
    openConnectionDialog();
    setStatus(`请先完成“${connection?.name || "当前"}”的接口地址和 API KEY。`);
    return;
  }

  const allowedModels = PROVIDER_MODELS[connection.id] || [];
  if (!allowedModels.includes(modelSelect.value)) {
    renderModelOptions();
    setStatus(`模型与“${connection.name}”接口不匹配，已自动切换为 ${modelSelect.value}。`);
    return;
  }

  if (!prompt) {
    promptInput.focus();
    setStatus("请输入提示词。");
    return;
  }

  const referenceMode = referenceModeSelect?.value || "auto";
  const unknownTokens = getUnknownTokens();
  if ((referenceMode === "auto" || referenceMode === "selected") && unknownTokens.length) {
    promptInput.focus();
    setStatus(`未识别参考图：${unknownTokens.join("，")}`);
    return;
  }

  let selectedRefs = getSelectedReferences(referenceMode);
  if (referenceMode === "selected" && !selectedRefs.length) {
    promptInput.focus();
    setStatus("当前选择的是只使用图几，请在提示词里输入 @ 选择参考图，或直接写图1、图2。");
    return;
  }

  const provider = getApiProvider();
  const options = {
    aspectRatio: sizeSelect.value,
    endpoint: getEndpoint(),
    model: modelSelect.value,
    provider,
    quality: qualitySelect.value,
    referenceMode,
    resolution: resolutionSelect?.value || "1K",
    size: provider === "geeknow" && modelSelect.value === GEEKNOW_SUNBURST_MODEL
      ? getGeeknowSunburstSize(sizeSelect.value, resolutionSelect?.value || "1K")
      : provider === "grsai"
      ? getGrsaiAspectRatio(modelSelect.value, sizeSelect.value, resolutionSelect?.value || "1K")
      : provider === "lk888"
      ? getLk888Tt2Size(sizeSelect.value, resolutionSelect?.value || "1K")
      : provider === "seventoken" && modelSelect.value === SEVENTOKEN_UPSCALE_MODEL
      ? getSevenTokenUpscaleSize(sizeSelect.value, resolutionSelect?.value || "1K")
      : provider === "qilingze" && modelSelect.value === QILINGZE_GPT25_MODEL
        ? getQilingzeGpt25Size(sizeSelect.value, resolutionSelect?.value || "1K")
        : aspectRatioToSize(sizeSelect.value, modelSelect.value, provider),
  };
  if (provider === "qilingze" && options.model === QILINGZE_GPT25_MODEL && selectedRefs.length > 4) {
    setStatus("GPT Image 2.5 最多支持 4 张参考图，请减少后重试。");
    return;
  }
  const taskCard = createTaskCard({
    connectionId: connection.id,
    model: options.model,
    options,
    prompt,
    provider: options.provider,
    selectedRefs,
    size: provider === "fmgo" && FMGO_25_MODELS.includes(options.model)
      ? `${options.aspectRatio} · ${options.resolution}`
      : provider === "grsai"
      ? `${options.aspectRatio}${isGrsaiPixelModel(options.model) ? ` · ${options.resolution} · ${options.size}` : ""}`
      : provider === "lk888"
      ? `${options.aspectRatio} · ${options.resolution}${options.model === LK888_TT2_MODEL ? ` · ${options.size}` : ""}`
      : (provider === "qilingze" && options.model === QILINGZE_GPT25_MODEL)
      || (provider === "seventoken" && options.model === SEVENTOKEN_UPSCALE_MODEL)
      ? `${options.aspectRatio} · ${options.resolution} · ${options.size}`
      : options.aspectRatio,
  });
  await executeTask(taskCard, apiKey);
};

