const downloadImage = async (image) => {
  const startDownload = (url) => {
    const link = document.createElement("a");
    link.href = url;
    link.download = image.filename;
    link.click();
  };

  if (image.blob) {
    const blobUrl = URL.createObjectURL(image.blob);
    startDownload(blobUrl);
    window.setTimeout(() => URL.revokeObjectURL(blobUrl), 1000);
    return;
  }

  if (image.url.startsWith("data:image/") || image.url.startsWith("blob:")) {
    startDownload(image.url);
    return;
  }

  try {
    const response = await fetch(image.url, { mode: "cors" });
    if (!response.ok) throw new Error(`HTTP ${response.status}`);
    const blobUrl = URL.createObjectURL(await response.blob());
    startDownload(blobUrl);
    window.setTimeout(() => URL.revokeObjectURL(blobUrl), 1000);
  } catch (error) {
    throw new Error(`图片临时地址已失效或禁止下载，请重新生成（${error?.message || error}）`);
  }
};

const favoriteImage = async (image, button) => {
  if (image.favoriteId) return;
  button.disabled = true;
  button.textContent = "收藏中";

  try {
    const record = await saveFavoriteImage(image);
    image.favoriteId = record.id;
    button.textContent = "已收藏";
    setStatus("图片和提示词已永久保存到本地收藏夹。");
  } catch (error) {
    button.disabled = false;
    button.textContent = "收藏";
    const message = error?.name === "QuotaExceededError"
      ? "浏览器本地空间不足，请先删除部分收藏。"
      : error?.message || String(error);
    setStatus(`收藏失败：${message}`);
  }
};

