const hasDraggedFiles = (event) => Array.from(event.dataTransfer?.types || []).includes("Files");

const setPageDragging = (isDragging) => {
  document.body.classList.toggle("is-page-dragging", isDragging);
  uploadBox.classList.toggle("is-dragging", isDragging);
  pageDropOverlay.setAttribute("aria-hidden", String(!isDragging));
};

document.addEventListener("dragenter", (event) => {
  if (document.body.classList.contains("batch-mode")) return;
  if (!hasDraggedFiles(event)) return;
  event.preventDefault();
  pageDragDepth += 1;
  setPageDragging(true);
});

document.addEventListener("dragover", (event) => {
  if (document.body.classList.contains("batch-mode")) return;
  if (!hasDraggedFiles(event)) return;
  event.preventDefault();
  event.dataTransfer.dropEffect = "copy";
  setPageDragging(true);
});

document.addEventListener("dragleave", (event) => {
  if (document.body.classList.contains("batch-mode")) return;
  if (!hasDraggedFiles(event)) return;
  event.preventDefault();
  pageDragDepth = Math.max(0, pageDragDepth - 1);
  if (!pageDragDepth) setPageDragging(false);
});

document.addEventListener("drop", (event) => {
  if (document.body.classList.contains("batch-mode")) return;
  if (!hasDraggedFiles(event)) return;
  event.preventDefault();
  pageDragDepth = 0;
  setPageDragging(false);
  void addReferences(event.dataTransfer?.files || []);
});

window.addEventListener("dragend", () => {
  pageDragDepth = 0;
  setPageDragging(false);
});

