const rewriteBatchGlobalMentions = (value, replacements) => {
  let text = String(value || "");
  const applicable = replacements
    .filter((item) => item.from && item.from !== item.to)
    .sort((left, right) => right.from.length - left.from.length)
    .map((item, index) => ({ ...item, placeholder: `\uE000global-ref-${index}\uE001` }));
  applicable.forEach(({ from, placeholder }) => {
    const escaped = from.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    text = text.replace(new RegExp(`${escaped}(?!\\d)`, "g"), placeholder);
  });
  applicable.forEach(({ placeholder, to }) => {
    text = text.split(placeholder).join(to);
  });
  return text;
};

const reindexBatchGlobalReferences = (category, removedMention = "") => {
  const refs = batchGlobalReferences[category];
  const replacements = removedMention ? [{ from: removedMention, to: "" }] : [];
  refs.forEach((ref, index) => {
    const nextMention = `全局图${index + 1}`;
    if (ref.mention !== nextMention) replacements.push({ from: ref.mention, to: nextMention });
  });
  const changed = replacements.some((item) => item.from && item.from !== item.to)
    || refs.some((ref, index) => ref.mention !== `全局图${index + 1}`);
  if (!changed) return false;

  batchGlobalPrompts[category] = rewriteBatchGlobalMentions(batchGlobalPrompts[category], replacements);
  batchJobs[category].forEach((job) => {
    job.promptInput.value = rewriteBatchGlobalMentions(job.promptInput.value, replacements);
    schedulePersistBatchJob(job, true);
  });
  refs.forEach((ref, index) => {
    ref.mention = `全局图${index + 1}`;
  });
  if (category === activeBatchCategory && batchGlobalPromptInput) {
    batchGlobalPromptInput.value = batchGlobalPrompts[category];
  }
  closeBatchMentionMenu();
  if (batchPersistenceReady) schedulePersistBatchSettings(true);
  else batchReferenceReindexPending = true;
  return true;
};

