const getBatchMentionItems = (textarea, category) => {
  const globalItems = batchGlobalReferences[category].map((ref) => ({ ...ref, scope: "global" }));
  if (textarea === batchGlobalPromptInput) return globalItems;
  const card = textarea.closest("[data-batch-job-id]");
  const job = card ? getBatchJob(card.dataset.batchJobId) : null;
  const localItems = (job?.refs || []).map((ref, index) => ({
    ...ref,
    mention: `图${index + 1}`,
    scope: "task",
  }));
  return [...localItems, ...globalItems];
};

const updateBatchMentionMenu = (textarea) => {
  if (!textarea || !textarea.matches("#batchGlobalPromptInput, .batch-job-prompt")) return closeBatchMentionMenu();
  const cursor = textarea.selectionStart ?? 0;
  const match = textarea.value.slice(0, cursor).match(/@([^\s@，。；：,.!?！？]*)$/);
  if (!match) return closeBatchMentionMenu();
  const category = getBatchMentionCategory(textarea);
  const query = match[1].toLowerCase();
  const items = getBatchMentionItems(textarea, category).filter((ref) =>
    !query || ref.mention.toLowerCase().includes(query) || ref.file.name.toLowerCase().includes(query));
  if (!items.length) return closeBatchMentionMenu();
  batchMentionState.textarea = textarea;
  batchMentionState.category = category;
  batchMentionState.start = cursor - match[0].length;
  batchMentionState.end = cursor;
  batchMentionState.items = items;
  batchMentionState.activeIndex = 0;
  batchMentionMenu.innerHTML = items.map((ref, index) => `
    <button class="batch-mention-option${index === 0 ? " is-active" : ""}" type="button" data-batch-mention-id="${escapeHtml(ref.id)}">
      <img src="${escapeHtml(ref.previewUrl)}" alt="" />
      <span><strong>${escapeHtml(ref.mention)}</strong><small>${ref.scope === "task" ? "当前任务" : "区块全局"} · ${escapeHtml(ref.file.name)}</small></span>
    </button>
  `).join("");
  const rect = textarea.getBoundingClientRect();
  batchMentionMenu.style.left = `${Math.max(12, Math.min(rect.left, window.innerWidth - 342))}px`;
  batchMentionMenu.style.top = `${Math.min(window.innerHeight - 270, rect.bottom + 6)}px`;
  batchMentionMenu.hidden = false;
};

