const locateBatchJobByName = (queryValue) => {
  const query = String(queryValue || "").trim().toLocaleLowerCase("zh-CN");
  if (!query) {
    setBatchStatus("请输入要查找的任务名称。");
    batchTaskSearchInput?.focus();
    return;
  }
  const jobs = Object.values(batchJobs).flat();
  const getName = (job) => job.nameInput.value.trim().toLocaleLowerCase("zh-CN");
  const job = jobs.find((item) => getName(item) === query)
    || jobs.find((item) => getName(item).includes(query));
  if (!job) {
    setBatchStatus(`没有找到名称包含“${queryValue.trim()}”的任务。`);
    return;
  }
  activeBatchStatusFilter = "all";
  setActiveBatchCategory(job.category);
  window.clearTimeout(batchSearchHighlightTimer);
  requestAnimationFrame(() => {
    job.card.classList.add("is-search-match");
    job.card.scrollIntoView({ behavior: "smooth", block: "center", inline: "nearest" });
    batchSearchHighlightTimer = window.setTimeout(() => job.card.classList.remove("is-search-match"), 2200);
  });
  setBatchStatus(`已定位到${BATCH_CATEGORY_LABELS[job.category]}区任务“${job.nameInput.value.trim()}”。`);
};

