const setBatchJobState = (job, state, label) => {
  job.status = state;
  job.card.classList.toggle("is-running", state === "running");
  job.card.classList.toggle("is-queued", state === "queued");
  job.card.classList.toggle("is-complete", state === "complete");
  job.card.classList.toggle("is-error", state === "error");
  job.state.textContent = label;
  const isBusy = state === "running" || state === "queued";
  job.generateButton.disabled = isBusy;
  job.generateButton.textContent = job.remoteTaskId ? "继续查询" : (state === "error" ? "重新生成" : "生成");
  job.deleteButton.disabled = isBusy;
  job.modifyButton.disabled = isBusy || !(job.result?.blob instanceof Blob);
  job.downloadButton.disabled = isBusy || !(job.result?.blob instanceof Blob);
  job.favoriteButton.disabled = isBusy || !(job.result?.blob instanceof Blob) || Boolean(job.favoriteId);
  job.favoriteButton.textContent = job.favoriteId ? "已收藏" : "收藏";
  applyBatchStatusFilter();
};

