    showBatchJobPlaceholder(job, "等待生成", "填写名称和提示词后生成图片");
    return;
  }
  const count = job.results.length;
  const index = job.resultIndex;
  job.visual.innerHTML = `
    <img src="${escapeHtml(job.result.objectUrl)}" alt="${escapeHtml(job.nameInput.value.trim() || "生成结果")}" data-batch-preview="${job.id}" />
    <div class="batch-result-history" aria-label="当前任务图片记录">
      <button type="button" data-batch-history="previous" aria-label="查看上一张图片" ${index === 0 ? "disabled" : ""}>‹</button>
      <span>${index + 1} / ${count}</span>
      <button type="button" data-batch-history="next" aria-label="查看下一张图片" ${index === count - 1 ? "disabled" : ""}>›</button>
    </div>
  `;
};

const selectBatchResult = (job, index) => {
  if (index < 0 || index >= job.results.length || index === job.resultIndex) return;
  job.resultIndex = index;
  job.result = job.results[index];
  job.favoriteId = job.result.favoriteId || "";
  renderBatchResult(job);
  setBatchJobState(job, job.status, job.state.textContent);
  schedulePersistBatchJob(job, true);
};

const removeBatchJob = (job) => {
  if (!job || ["running", "queued"].includes(job.status)) return false;
  job.refs.forEach((ref) => URL.revokeObjectURL(ref.previewUrl));
  releaseBatchJobResults(job);
  batchJobs[job.category] = batchJobs[job.category].filter((item) => item !== job);
  job.card.remove();
  renderBatchEmptyState(job.category);
  deletePersistedBatchJob(job.id);
  applyBatchStatusFilter();
  return true;
};

const addBatchJob = (category = activeBatchCategory, data = {}, behavior = {}) => {
  const panel = batchPanels.get(category);
  if (!panel) return null;
  const id = String(data.id || nextBatchJobId++);
  const numericId = Number(id);
  if (Number.isFinite(numericId)) nextBatchJobId = Math.max(nextBatchJobId, numericId + 1);
  const ordinal = batchJobs[category].length + 1;
  const card = document.createElement("article");
  card.className = "batch-job-card";
  card.dataset.batchJobId = id;
  card.innerHTML = `
