      <div class="batch-job-actions">
        <button class="small-button batch-generate-one" type="button">生成</button>
        <button class="small-button batch-modify-button" type="button" disabled>修改</button>
        <button class="small-button batch-download-one" type="button" disabled>下载</button>
        <button class="small-button batch-favorite-button" type="button" disabled>收藏</button>
        <button class="small-button batch-delete-button" type="button">删除</button>
      </div>
