  panel.querySelector(".batch-empty")?.remove();
  const prepend = Boolean(behavior.prepend);
  if (prepend) panel.prepend(card);
  else panel.append(card);
  const job = {
    card,
    category,
    deleteButton: card.querySelector(".batch-delete-button"),
    downloadButton: card.querySelector(".batch-download-one"),
    favoriteButton: card.querySelector(".batch-favorite-button"),
    favoriteId: data.favoriteId || "",
    generateButton: card.querySelector(".batch-generate-one"),
    id,
    lastOptions: null,
    modifyButton: card.querySelector(".batch-modify-button"),
    nameInput: card.querySelector(".batch-job-name"),
    promptInput: card.querySelector(".batch-job-prompt"),
    refs: [],
    remotePollUrl: "",
    remoteTaskId: "",
    result: null,
    resultIndex: -1,
    results: [],
    state: card.querySelector(".batch-job-state"),
    status: "idle",
    visual: card.querySelector(".batch-result"),
  };
  if (prepend) batchJobs[category].unshift(job);
  else batchJobs[category].push(job);
  renderBatchResult(job);
  renderBatchEmptyState(category);
  applyBatchStatusFilter();
  if (!data.restoring) {
    if (prepend) batchJobs[category].forEach((item) => schedulePersistBatchJob(item, true));
    else schedulePersistBatchJob(job, true);
  }
  return job;
};

const requestResult = (request, errorMessage) => new Promise((resolve, reject) => {
  request.onsuccess = () => resolve(request.result);
  request.onerror = () => reject(request.error || new Error(errorMessage));
});

const toStoredFile = (ref) => ({
  blob: ref.file.slice(0, ref.file.size, ref.file.type || "image/png"),
  id: ref.id,
  lastModified: ref.file.lastModified || Date.now(),
  mention: ref.mention,
  name: ref.file.name,
  type: ref.file.type || "image/png",
});

const fromStoredFile = (record, fallbackName) => {
  if (!(record?.blob instanceof Blob)) return null;
  const file = new File([record.blob], record.name || fallbackName, {
    lastModified: record.lastModified || Date.now(),
    type: record.type || record.blob.type || "image/png",
  });
  return {
    file,
    id: record.id || `${Date.now()}-${Math.random().toString(16).slice(2)}`,
    mention: record.mention || "",
    previewUrl: URL.createObjectURL(file),
  };
};

const putBatchRecord = async (record) => {
  const database = await openReferenceDatabase();
  const transaction = database.transaction(BATCH_DB_STORE, "readwrite");
  transaction.objectStore(BATCH_DB_STORE).put(record);
  await waitForTransaction(transaction);
};

const setDraftsStatus = (message) => {
  if (draftsStatus) draftsStatus.textContent = message;
};

const renderDrafts = () => {
  if (!draftsGrid || !draftCount || !draftsEmpty) return;
  draftCount.textContent = `${drafts.length} 个草稿`;
  draftsEmpty.hidden = drafts.length > 0;
  draftsGrid.replaceChildren();
  drafts.forEach((draft) => {
    const card = document.createElement("article");
    card.className = "draft-card";
    card.dataset.draftId = draft.id;
    card.innerHTML = `
      <div class="draft-card-mark" aria-hidden="true">稿</div>
      <div class="draft-card-copy">
        <input class="draft-name-input" type="text" maxlength="80" value="${escapeHtml(draft.name)}" aria-label="草稿名称" />
        <span>独立保存人物、场景、道具及所有图片记录</span>
      </div>
      <div class="draft-card-actions">
        <button class="dark-button" type="button" data-open-draft="${escapeHtml(draft.id)}">进入工作台</button>
        <button class="ghost-button danger" type="button" data-delete-draft="${escapeHtml(draft.id)}">删除草稿</button>
      </div>
    `;
    draftsGrid.append(card);
  });
};

const persistDraftMeta = async (draft) => {
  await putBatchRecord({
    createdAt: draft.createdAt,
    id: draft.id,
    key: getDraftMetaKey(draft.id),
    kind: "draft-meta",
    name: draft.name,
    updatedAt: draft.updatedAt,
  });
};

const loadDraftsAndMigrateLegacyWorkspace = async () => {
  const database = await openReferenceDatabase();
  const transaction = database.transaction(BATCH_DB_STORE, "readwrite");
  const store = transaction.objectStore(BATCH_DB_STORE);
  const records = await requestResult(store.getAll(), "无法读取草稿列表。");
  const legacyRecords = records.filter((record) => (
    record.key === BATCH_SETTINGS_KEY || String(record.key || "").startsWith("job:")
  ));
  const metaRecords = records.filter((record) => String(record.key || "").startsWith(DRAFT_META_PREFIX));
  if (legacyRecords.length) {
    const draftId = window.crypto?.randomUUID?.() || `draft-${Date.now()}-${Math.random().toString(16).slice(2)}`;
    const now = Date.now();
    const draft = {
      createdAt: now,
      id: draftId,
      key: getDraftMetaKey(draftId),
      kind: "draft-meta",
      name: "原工作台",
      updatedAt: now,
    };
    store.put(draft);
    legacyRecords.forEach((record) => {
      const legacyKey = String(record.key || "");
      const migratedKey = legacyKey === BATCH_SETTINGS_KEY
        ? getDraftSettingsKey(draftId)
        : getDraftJobKey(draftId, legacyKey.slice("job:".length));
      store.put({ ...record, draftId, key: migratedKey });
      store.delete(record.key);
    });
    metaRecords.push(draft);
  }
  await waitForTransaction(transaction);
  drafts = metaRecords
    .map((record) => ({
      createdAt: Number(record.createdAt || Date.now()),
      id: String(record.id || String(record.key).slice(DRAFT_META_PREFIX.length)),
      name: String(record.name || "未命名草稿"),
      updatedAt: Number(record.updatedAt || record.createdAt || Date.now()),
    }))
    .sort((left, right) => right.updatedAt - left.updatedAt);
  renderDrafts();
  setDraftsStatus(legacyRecords.length ? "旧工作台已安全迁移为“原工作台”草稿。" : `已读取 ${drafts.length} 个本地草稿。`);
};

const clearBatchWorkspaceMemory = () => {
  batchPersistenceReady = false;
  batchReferenceReindexPending = false;
  batchJobPersistTimers.forEach((timer) => window.clearTimeout(timer));
  batchJobPersistTimers.clear();
  if (batchSettingsPersistTimer) window.clearTimeout(batchSettingsPersistTimer);
  batchSettingsPersistTimer = 0;
  Object.values(batchJobs).forEach((jobs) => {
    jobs.forEach((job) => {
      job.refs.forEach((ref) => URL.revokeObjectURL(ref.previewUrl));
      releaseBatchJobResults(job);
      job.card.remove();
    });
    jobs.splice(0, jobs.length);
  });
  Object.keys(batchGlobalReferences).forEach((category) => {
    batchGlobalReferences[category].forEach((ref) => URL.revokeObjectURL(ref.previewUrl));
    batchGlobalReferences[category] = [];
    batchGlobalPrompts[category] = "";
    batchGlobalReferenceCounters[category] = 0;
    renderBatchEmptyState(category);
  });
  activeBatchCategory = "character";
  nextBatchJobId = 1;
  modifyingBatchJobId = "";
  if (batchTaskSearchInput) batchTaskSearchInput.value = "";
  if (previewDialog.open) previewDialog.close();
  if (batchModifyDialog.open) batchModifyDialog.close();
  closeBatchMentionMenu();
  renderBatchGlobalReferences();
  updateSelectAllButton();
};

const openDraftWorkspace = async (draftId) => {
  const draft = drafts.find((item) => item.id === draftId);
  if (!draft) return;
  clearBatchWorkspaceMemory();
  activeDraftId = draft.id;
  currentDraftName.textContent = draft.name;
  draftsHome.hidden = true;
  batchWorkspace.hidden = false;
  renderBatchModelOptions();
  try {
    const resumableJobs = await restoreBatchWorkspace(draft.id);
    batchPersistenceReady = true;
    if (batchReferenceReindexPending) {
      batchReferenceReindexPending = false;
      await Promise.all(Object.values(batchJobs).flat().map((job) => persistBatchJob(job)));
      await persistBatchSettings();
    }
    setActiveBatchCategory(activeBatchCategory);
    const restoredJobs = Object.values(batchJobs).flat().length;
    setBatchStatus(restoredJobs
      ? `已恢复“${draft.name}”的 ${restoredJobs} 个任务及本地图片记录。`
      : `“${draft.name}”暂无任务，可新建或批量导入。`);
    if (resumableJobs.length) {
      setBatchStatus(`已恢复 ${resumableJobs.length} 个正在生成的任务，正在使用原任务编号继续查询，不会重新提交。`);
      resumableJobs.forEach((job) => void queueBatchResume(job));
    }
  } catch (error) {
    batchPersistenceReady = true;
    setActiveBatchCategory("character");
    setBatchStatus(`草稿记录恢复失败：${error?.message || error}`);
  }
};

const showDraftsHome = async () => {
  if (batchQueueRunning || activeBatchGenerationCount || pendingBatchGenerations.length) {
    setBatchStatus("当前仍有生成任务，请等待批量任务结束后再返回草稿列表。");
    return;
  }
  if (activeDraftId && batchPersistenceReady) {
    await Promise.all(Object.values(batchJobs).flat().map((job) => persistBatchJob(job)));
    await persistBatchSettings();
  }
  clearBatchWorkspaceMemory();
  activeDraftId = "";
  batchWorkspace.hidden = true;
  draftsHome.hidden = false;
  renderDrafts();
};

const createDraft = async (nameValue) => {
  const name = String(nameValue || "").trim();
  if (!name) throw new Error("请填写草稿名称。");
  const now = Date.now();
  const draft = {
    createdAt: now,
    id: window.crypto?.randomUUID?.() || `draft-${now}-${Math.random().toString(16).slice(2)}`,
    name,
    updatedAt: now,
  };
  await persistDraftMeta(draft);
  drafts.unshift(draft);
  renderDrafts();
  await openDraftWorkspace(draft.id);
};

const deleteDraftAndCache = async (draftId) => {
  const draft = drafts.find((item) => item.id === draftId);
  if (!draft) return;
  if (!window.confirm(`确定删除草稿“${draft.name}”吗？该草稿的任务、生成图片、参考图和全部缓存都会永久删除。`)) return;
  clearTimeout(draftNamePersistTimers.get(draftId));
  draftNamePersistTimers.delete(draftId);
  const prefix = getDraftPrefix(draftId);
  await Promise.all([...batchJobWriteChains.entries()]
    .filter(([key]) => key.startsWith(prefix))
    .map(([, write]) => write.catch(() => {})));
  const database = await openReferenceDatabase();
  const transaction = database.transaction(BATCH_DB_STORE, "readwrite");
  const store = transaction.objectStore(BATCH_DB_STORE);
  const keys = await requestResult(store.getAllKeys(), "无法读取草稿缓存索引。");
  keys.forEach((key) => {
    const value = String(key || "");
    if (value === getDraftMetaKey(draftId) || value.startsWith(prefix)) store.delete(key);
  });
  await waitForTransaction(transaction);
  drafts = drafts.filter((item) => item.id !== draftId);
  renderDrafts();
  setDraftsStatus(`草稿“${draft.name}”及其全部本地图片缓存已删除。`);
};

const reportBatchPersistenceError = (error) => {
  const message = error?.name === "QuotaExceededError"
    ? "本地存储空间不足，最新记录未能保存；请释放浏览器磁盘空间。"
    : `本地记录保存失败：${error?.message || error}`;
  setBatchStatus(message);
};

const persistBatchJob = async (job) => {
  if (!batchPersistenceReady || !activeDraftId || !job?.card?.isConnected) return false;
  const key = getDraftJobKey(activeDraftId, job.id);
  const record = {
    category: job.category,
    connectionId: job.connectionId || "",
    draftId: activeDraftId,
    favoriteId: job.favoriteId || "",
    id: job.id,
    key,
    lastModifyPrompt: job.lastModifyPrompt || "",
    lastOptions: job.lastOptions ? { ...job.lastOptions } : null,
    lastPrompt: job.lastPrompt || "",
    name: job.nameInput.value,
    order: batchJobs[job.category].indexOf(job),
    prompt: job.promptInput.value,
    refs: job.refs.map(toStoredFile),
    remotePollUrl: job.remotePollUrl || "",
    remoteTaskId: job.remoteTaskId || "",
    results: serializeBatchResults(job),
    resultIndex: job.resultIndex,
    resultSourceUrl: String(job.result?.sourceUrl || ""),
    routeDetail: job.card.querySelector("[data-route-detail]")?.textContent || "",
    stateLabel: job.state.textContent,
    status: job.remoteTaskId ? "running" : (job.result ? "complete" : (job.status === "running" ? "idle" : job.status)),
  };
  const previousWrite = batchJobWriteChains.get(key) || Promise.resolve();
  const write = previousWrite.catch(() => {}).then(() => putBatchRecord(record));
  batchJobWriteChains.set(key, write);
  try {
    await write;
    return true;
  } catch (error) {
    reportBatchPersistenceError(error);
    return false;
  } finally {
    if (batchJobWriteChains.get(key) === write) batchJobWriteChains.delete(key);
  }
};

const schedulePersistBatchJob = (job, immediate = false) => {
  if (!batchPersistenceReady || !job) return;
  const oldTimer = batchJobPersistTimers.get(job.id);
  if (oldTimer) window.clearTimeout(oldTimer);
  if (immediate) {
    batchJobPersistTimers.delete(job.id);
    void persistBatchJob(job);
    return;
  }
  const timer = window.setTimeout(() => {
    batchJobPersistTimers.delete(job.id);
    void persistBatchJob(job);
  }, 500);
  batchJobPersistTimers.set(job.id, timer);
};

const deletePersistedBatchJob = (jobId) => {
  if (!batchPersistenceReady || !activeDraftId) return;
  const draftId = activeDraftId;
  const key = getDraftJobKey(draftId, jobId);
  void (async () => {
    try {
      await (batchJobWriteChains.get(key) || Promise.resolve()).catch(() => {});
      const database = await openReferenceDatabase();
      const transaction = database.transaction(BATCH_DB_STORE, "readwrite");
      transaction.objectStore(BATCH_DB_STORE).delete(key);
      await waitForTransaction(transaction);
    } catch (error) {
      reportBatchPersistenceError(error);
    }
  })();
};

const persistBatchSettings = async () => {
  if (!batchPersistenceReady || !activeDraftId) return;
  try {
    const globalReferences = {};
    Object.keys(batchGlobalReferences).forEach((category) => {
      globalReferences[category] = batchGlobalReferences[category].map(toStoredFile);
    });
    await putBatchRecord({
      activeCategory: activeBatchCategory,
      batchModelByConnection: { ...batchModelByConnection },
      globalPrompts: { ...batchGlobalPrompts },
      globalReferences,
      globalReferenceCounters: { ...batchGlobalReferenceCounters },
      draftId: activeDraftId,
      key: getDraftSettingsKey(activeDraftId),
      nextBatchJobId,
      quality: batchQualitySelect.value,
      resolution: batchResolutionSelect?.value || "1K",
      size: batchSizeSelect.value,
    });
  } catch (error) {
    reportBatchPersistenceError(error);
  }
};

const schedulePersistBatchSettings = (immediate = false) => {
  if (!batchPersistenceReady) return;
  if (batchSettingsPersistTimer) window.clearTimeout(batchSettingsPersistTimer);
  if (immediate) {
    batchSettingsPersistTimer = 0;
    void persistBatchSettings();
    return;
  }
  batchSettingsPersistTimer = window.setTimeout(() => {
    batchSettingsPersistTimer = 0;
    void persistBatchSettings();
  }, 500);
};

const restoreBatchWorkspace = async (draftId) => {
  const resumableJobs = [];
  const database = await openReferenceDatabase();
  const transaction = database.transaction(BATCH_DB_STORE, "readonly");
  const records = await requestResult(
    transaction.objectStore(BATCH_DB_STORE).getAll(),
    "无法读取批量工作台本地记录。",
  );
  const draftPrefix = getDraftPrefix(draftId);
  const draftRecords = records.filter((record) => String(record.key || "").startsWith(draftPrefix));
  const settings = draftRecords.find((record) => record.key === getDraftSettingsKey(draftId));
  if (settings) {
    Object.assign(batchModelByConnection, settings.batchModelByConnection || {});
    Object.keys(batchGlobalPrompts).forEach((category) => {
      batchGlobalPrompts[category] = String(settings.globalPrompts?.[category] || "");
      batchGlobalReferenceCounters[category] = Number(settings.globalReferenceCounters?.[category] || 0);
      batchGlobalReferences[category] = (settings.globalReferences?.[category] || [])
        .map((record, index) => fromStoredFile(record, `${category}-global-${index + 1}.png`))
        .filter(Boolean);
    });
    nextBatchJobId = Math.max(1, Number(settings.nextBatchJobId || 1));
    renderBatchModelOptions();
    if (Array.from(batchSizeSelect.options).some((option) => option.value === settings.size)) batchSizeSelect.value = settings.size;
    if (Array.from(batchResolutionSelect.options).some((option) => option.value === settings.resolution)) batchResolutionSelect.value = settings.resolution;
    if (Array.from(batchQualitySelect.options).some((option) => option.value === settings.quality)) batchQualitySelect.value = settings.quality;
    activeBatchCategory = batchJobs[settings.activeCategory] ? settings.activeCategory : "character";
  }

  draftRecords
    .filter((record) => String(record.key || "").startsWith(`${draftPrefix}job:`) && batchJobs[record.category])
    .sort((left, right) => left.category.localeCompare(right.category) || Number(left.order || 0) - Number(right.order || 0))
    .forEach((record) => {
      const job = addBatchJob(record.category, {
        id: record.id,
        name: record.name,
        prompt: record.prompt,
        restoring: true,
      });
      job.refs = (record.refs || [])
        .map((ref, index) => fromStoredFile(ref, `task-${job.id}-reference-${index + 1}.png`))
        .filter(Boolean);
      job.connectionId = record.connectionId || "";
      job.favoriteId = record.favoriteId || "";
      job.lastOptions = record.lastOptions || null;
      job.lastModifyPrompt = record.lastModifyPrompt || "";
      job.lastPrompt = record.lastPrompt || record.prompt || "";
      job.remotePollUrl = record.remotePollUrl || "";
      job.remoteTaskId = record.remoteTaskId || "";
      job.results = restoreBatchResults(record);
      if (job.results.length) {
        job.resultIndex = Math.max(0, Math.min(Number.isInteger(record.resultIndex) ? record.resultIndex : job.results.length - 1, job.results.length - 1));
        job.result = job.results[job.resultIndex];
        job.favoriteId = job.result.favoriteId || "";
        renderBatchResult(job);
      }
      const route = job.card.querySelector("[data-route-detail]");
      if (route && record.routeDetail) route.textContent = record.routeDetail;
      const hasRunningRemoteTask = Boolean(job.remoteTaskId);
      const wasRemoteOnly = !job.result && !hasRunningRemoteTask && Boolean(record.resultSourceUrl);
      const interruptedQueue = !hasRunningRemoteTask && record.status === "queued";
      const restoredStatus = job.result ? "complete" : (hasRunningRemoteTask ? "queued" : (wasRemoteOnly ? "error" : (interruptedQueue ? "idle" : (record.status || "idle"))));
      const restoredLabel = job.result ? "已恢复" : (hasRunningRemoteTask ? "恢复生成进度" : (wasRemoteOnly ? "请重新生成" : (interruptedQueue ? "排队已中断" : (record.stateLabel || "待生成"))));
      setBatchJobState(job, restoredStatus, restoredLabel);
      if (hasRunningRemoteTask) {
        showBatchJobPlaceholder(job, "恢复生成进度", `${job.remoteTaskId} · 正在等待继续查询`);
        resumableJobs.push(job);
      }
      if (wasRemoteOnly) {
        showBatchJobPlaceholder(job, "旧远程记录已失效", "请点击重新生成；新结果会先保存到本地后再显示成功。");
      }
      if (interruptedQueue && !job.result) {
        showBatchJobPlaceholder(job, "排队已中断", "刷新前尚未发送的任务，请重新勾选后批量生成。");
      }
      renderBatchReferences(job);
    });
  Object.keys(batchGlobalReferences).forEach((category) => {
    reindexBatchGlobalReferences(category);
  });
  return resumableJobs;
};

const validateBatchJob = (job, options) => {
  const name = job.nameInput.value.trim();
  const prompt = job.promptInput.value.trim();
  if (!name) throw new Error("请先填写图片名称。");
  if (!prompt) throw new Error(`“${name}”还没有提示词。`);
  if (/[<>:"/\\|?*]/.test(name) || /[. ]$/.test(name)) {
    throw new Error(`“${name}”不能作为文件名，请去掉 \\ / : * ? \" < > | 或末尾空格、句点。`);
  }
  return { name, prompt };
};

const runBatchJob = async (job, configuration = {}) => {
  const options = { ...(configuration.options || getBatchOptions()) };
  const connectionId = configuration.connectionId || activeConnectionId;
  const connection = connectionProfiles.find((item) => item.id === connectionId);
  const apiKey = configuration.apiKey || connection?.apiKey || "";
  const isModification = Boolean(configuration.internalReference);
  const isRemoteResume = Boolean(configuration.resumeRemote && job.remoteTaskId);
  const originalResult = job.result;
  let validated;
  try {
    validated = validateBatchJob(job, options);
    if (!connection?.endpoint || !apiKey) throw new Error(`请先完成“${connection?.name || "当前接口"}”的接口地址和 API KEY 设置。`);
  } catch (error) {
    setBatchJobState(job, "error", "配置有误");
    if (job.result) renderBatchResult(job);
    else showBatchJobPlaceholder(job, "无法生成", error.message);
    setBatchStatus(error.message);
    schedulePersistBatchJob(job, true);
    return false;
  }

  const taskPrompt = isModification
    ? `请仅根据以下修改要求编辑内部参考图，保持未提及的主体、画风、构图和细节不变。\n修改要求：${configuration.modifyPrompt}`
    : validated.prompt;
  const globalPrompt = batchGlobalPrompts[job.category].trim();
  const currentPrompt = globalPrompt ? `${globalPrompt}\n\n${taskPrompt}` : taskPrompt;
  const prompt = isRemoteResume && job.lastPrompt ? job.lastPrompt : currentPrompt;
  const localRefs = configuration.internalReference
    ? [configuration.internalReference]
    : job.refs.map((ref) => ({ ...ref }));
  const mentionedGlobalRefs = getMentionedBatchGlobalReferences(job.category, prompt);
  const selectedRefs = [...localRefs, ...mentionedGlobalRefs.map((ref) => ({ ...ref }))];
  if (options.provider === "qilingze" && options.model === QILINGZE_GPT25_MODEL && selectedRefs.length > 4) {
    const message = `“${validated.name}”本次共引用 ${selectedRefs.length} 张图片，GPT Image 2.5 最多支持 4 张。`;
    setBatchJobState(job, "error", "参考图过多");
    if (!job.result) showBatchJobPlaceholder(job, "无法生成", message);
    setBatchStatus(message);
    schedulePersistBatchJob(job, true);
    return false;
  }
  const adapter = {
    card: job.card,
    id: job.id,
    meta: job.card,
    onRemoteTask: ({ pollUrl, taskId }) => {
      const changed = job.remoteTaskId !== taskId || job.remotePollUrl !== pollUrl;
      job.remoteTaskId = taskId;
      job.remotePollUrl = pollUrl;
      if (changed) schedulePersistBatchJob(job, true);
    },
    visual: job.visual,
  };

  job.connectionId = connectionId;
  job.lastOptions = { ...options, endpoint: connection.endpoint };
  job.lastModifyPrompt = isModification ? configuration.modifyPrompt : job.lastModifyPrompt;
  job.lastPrompt = prompt;
  setBatchJobState(job, "running", isRemoteResume ? "继续查询" : (isModification ? "正在修改" : "正在生成"));
  updateTaskVisual(adapter, isRemoteResume ? "恢复生成进度" : (isModification ? "修改中" : "提交任务"), isRemoteResume
    ? `${job.remoteTaskId} · 使用原任务编号继续查询`
    : `${connection.name} · ${options.model}`);
  try {
    const imageUrl = isRemoteResume
      ? await waitForImage({
        id: job.remoteTaskId,
        status: "in_progress",
        task: { id: job.remoteTaskId, status_url: job.remotePollUrl },
      }, apiKey, adapter, options)
      : await submitGeneration(apiKey, adapter, prompt, selectedRefs, options);
    updateTaskVisual(adapter, "正在取回图片", `${connection.name} 已生成完成，正在保存图片到本地`);
    const blob = await getGeneratedImageBlob(imageUrl, apiKey);
    const result = {
      blob,
      createdAt: Date.now(),
      favoriteId: "",
      objectUrl: URL.createObjectURL(blob),
      options: { ...job.lastOptions },
      prompt,
      sourceUrl: imageUrl,
    };
    job.results.push(result);
    job.resultIndex = job.results.length - 1;
    job.result = result;
    job.favoriteId = "";
    job.remotePollUrl = "";
    job.remoteTaskId = "";
    renderBatchResult(job);
    setBatchJobState(job, "complete", isModification
      ? "修改完成"
      : "生成完成");
    if (!(await persistBatchJob(job))) {
      setBatchJobState(job, "error", "图片未保存");
      setBatchStatus(`“${validated.name}”已生成，但本地图片记录保存失败；请先下载当前图片并检查浏览器存储空间。`);
      return false;
    }
    return true;
  } catch (error) {
    const message = classifyError(error);
    if (error?.isRemoteTerminalFailure) {
      job.remotePollUrl = "";
      job.remoteTaskId = "";
    }
    job.result = originalResult;
    if (job.result) renderBatchResult(job);
    else showBatchJobPlaceholder(job, job.remoteTaskId ? "查询中断" : "生成失败", message);
    setBatchJobState(job, "error", job.remoteTaskId ? "可继续查询" : "生成失败");
    setBatchStatus(`“${validated.name}”失败：${message}`);
    schedulePersistBatchJob(job, true);
    return false;
  }
};

const startNextBatchGeneration = () => {
  if (activeBatchGenerationCount >= MAX_BATCH_CONCURRENCY) return;
  const entry = pendingBatchGenerations.shift();
  if (!entry) return;
  activeBatchGenerationCount += 1;
  if (entry.configuration.batchRun) {
    entry.configuration.batchRun.started += 1;
    entry.configuration.batchRun.startedJobs?.add(entry.job);
  }
  void runBatchJob(entry.job, entry.configuration)
    .then(entry.resolve)
    .catch(() => entry.resolve(false))
    .finally(() => {
      activeBatchGenerationCount -= 1;
      startNextBatchGeneration();
    });
};

const queueBatchGeneration = (job, configuration = {}) => new Promise((resolve) => {
  pendingBatchGenerations.push({
    job, configuration, resolve,
    previousStatus: job.status,
    previousLabel: job.state.textContent,
    previousVisual: job.visual.innerHTML,
  });
  if (activeBatchGenerationCount >= MAX_BATCH_CONCURRENCY) {
    setBatchJobState(job, "queued", "排队中");
    if (!job.result) showBatchJobPlaceholder(job, "排队中", `等待并发空位；当前最多 ${MAX_BATCH_CONCURRENCY} 个任务同时生成`);
    schedulePersistBatchJob(job, true);
  }
  startNextBatchGeneration();
});

const pauseBatchGeneration = (batchRun) => {
  if (!batchRun || batchRun.paused) return;
  batchRun.paused = true;
  const restoredJobs = new Set();
  const restoreJob = (job, fallback) => {
    const previous = batchRun.originalStates?.get(job) || fallback;
    if (!previous || restoredJobs.has(job)) return;
    job.visual.innerHTML = previous.visual;
    setBatchJobState(job, previous.status, previous.label);
    schedulePersistBatchJob(job, true);
    restoredJobs.add(job);
  };
  for (let index = pendingBatchGenerations.length - 1; index >= 0; index -= 1) {
    const entry = pendingBatchGenerations[index];
    if (entry.configuration.batchRun !== batchRun) continue;
    pendingBatchGenerations.splice(index, 1);
    restoreJob(entry.job, { status: entry.previousStatus, label: entry.previousLabel, visual: entry.previousVisual });
    entry.resolve(false);
  }
  batchRun.originalStates?.forEach((previous, job) => {
    if (!batchRun.startedJobs.has(job)) restoreJob(job, previous);
  });
};

const queueBatchResume = (job) => {
  const connectionId = job.connectionId || activeConnectionId;
  const connection = connectionProfiles.find((item) => item.id === connectionId);
  if (!job.remoteTaskId || !connection?.apiKey || !job.lastOptions) {
    setBatchJobState(job, "error", "等待接口配置");
    showBatchJobPlaceholder(job, "无法恢复生成进度", "没有找到原接口配置，请检查接口设置后点击继续查询。");
    return Promise.resolve(false);
  }
  return queueBatchGeneration(job, {
    apiKey: connection.apiKey,
    connectionId,
    options: { ...job.lastOptions, endpoint: connection.endpoint },
    resumeRemote: true,
  });
};

const normalizeBatchCategory = (value, fallback = activeBatchCategory) => {
  const key = String(value || "").trim().toLowerCase();
  return BATCH_CATEGORY_ALIASES[key] || fallback;
};

const normalizeBatchEntry = (raw, fallbackCategory, index) => {
  if (typeof raw === "string") {
    return {
      category: fallbackCategory,
      name: `${BATCH_CATEGORY_LABELS[fallbackCategory]}${index + 1}`,
      prompt: raw.trim(),
    };
  }
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) return null;
  const category = normalizeBatchCategory(raw.category ?? raw.type ?? raw.分类 ?? raw.类型, fallbackCategory);
  const name = String(
    raw.name ?? raw.title ?? raw.名称 ?? raw.名字
    ?? raw.人物名称 ?? raw.角色名称 ?? raw.场景名称 ?? raw.场景设定 ?? raw.道具名称
    ?? `${BATCH_CATEGORY_LABELS[category]}${index + 1}`
  ).trim();
  const prompt = String(
    raw.prompt ?? raw.description ?? raw.text ?? raw.提示词 ?? raw.描述
    ?? raw.人物描述 ?? raw.角色描述 ?? raw.外观描述 ?? raw.场景描述 ?? raw.道具描述
    ?? ""
  ).trim();
  return { category, name, prompt };
};

const collectBatchImportEntries = (data) => {
  if (Array.isArray(data)) {
    return data.map((item, index) => normalizeBatchEntry(item, activeBatchCategory, index)).filter(Boolean);
  }
  if (Array.isArray(data?.tasks)) {
    return data.tasks.map((item, index) => normalizeBatchEntry(item, activeBatchCategory, index)).filter(Boolean);
  }
  const grouped = [];
  Object.entries(data || {}).forEach(([key, value]) => {
    const category = BATCH_CATEGORY_ALIASES[String(key).trim().toLowerCase()];
    if (!category) return;
    const values = Array.isArray(value) ? value : [value];
    values.forEach((item, index) => {
      const normalized = normalizeBatchEntry(item, category, index);
      if (normalized) grouped.push({ ...normalized, category });
    });
  });
  return grouped.length ? grouped : [normalizeBatchEntry(data, activeBatchCategory, 0)].filter(Boolean);
};

const parsePastedJson = (value) => {
  const text = String(value || "").trim();
  if (!text) throw new Error("请先粘贴 JSON 文本");
  const withoutFence = text
    .replace(/^```(?:json)?\s*/i, "")
    .replace(/\s*```$/, "")
    .trim();
  return JSON.parse(withoutFence);
};

const parseRoleTextEntries = (value) => {
  const text = String(value || "").replace(/\r\n?/g, "\n").trim();
  const headers = [...text.matchAll(/^[ \t]*(?:(?:[-+*]|\d+[.、)])\s+)?\*\*([^*\n]+?)\*\*[ \t]*[：:][ \t]*/gm)];
  if (!headers.length) throw new Error("角色文本请使用 **角色名**：角色描述，每个角色另起一行。");
  if (text.slice(0, headers[0].index).trim()) throw new Error("请从第一条 **角色名**：角色描述开始粘贴。");
  return headers.map((header, index) => {
    const name = header[1].trim();
    const prompt = text.slice(header.index + header[0].length, headers[index + 1]?.index ?? text.length).trim();
    if (!name || !prompt) throw new Error(`第 ${index + 1} 个角色的名称或描述为空。`);
    return { category: "character", name, prompt };
  });
};

const parseBatchImportText = (value) => {
  const text = String(value || "").trim();
  if (!text) throw new Error("请先粘贴要导入的文本。");
  const withoutFence = text.replace(/^```(?:json|text|markdown)?\s*/i, "").replace(/\s*```$/, "").trim();
  if (/^[\[{]/.test(withoutFence)) {
    const data = parsePastedJson(withoutFence);
    return collectBatchImportEntries(data);
  }
  return parseRoleTextEntries(withoutFence);
};

const importBatchJsonText = (jsonText) => {
  try {
    const entries = parseBatchImportText(jsonText);
    if (!entries.length) throw new Error("文本中没有可导入的任务。");
    activeBatchStatusFilter = "all";
    entries.forEach((entry) => addBatchJob(entry.category, entry));
    const destinationCategory = entries.some((entry) => entry.category === activeBatchCategory)
      ? activeBatchCategory
      : entries[0].category;
    setActiveBatchCategory(destinationCategory);
    setBatchStatus(`已从粘贴的文本导入 ${entries.length} 个任务。`);
    return entries.length;
  } catch (error) {
    setBatchStatus(`导入失败：${error.message}`);
    throw error;
  }
};

