const getBatchDownloadFilename = (job) => {
  const name = job.nameInput.value.trim();
  if (!name) throw new Error("存在未填写名称的图片，无法批量下载。");
  if (/[<>:"/\\|?*]/.test(name) || /[. ]$/.test(name)) {
    throw new Error(`“${name}”包含 Windows 文件名不支持的字符。`);
  }
  if (/\.(png|jpe?g|webp)$/i.test(name)) return name;
  const type = job.result?.blob?.type || "image/png";
  const extension = type.includes("jpeg") ? ".jpg" : type.includes("webp") ? ".webp" : ".png";
  return `${name}${extension}`;
};

const downloadBatchJob = (job) => {
  if (!(job?.result?.blob instanceof Blob)) return "none";
  const anchor = document.createElement("a");
  anchor.href = job.result.objectUrl;
  anchor.download = getBatchDownloadFilename(job);
  document.body.append(anchor);
  anchor.click();
  anchor.remove();
  return "local";
};

