  jobs.forEach((job) => {
    void queueBatchGeneration(job, {
      apiKey: connection.apiKey,
      batchRun,
      connectionId: connection.id,
      options: { ...options, endpoint: connection.endpoint },
    }).then(() => {
      batchRun.finished += 1;
      if (activeBatchRun !== batchRun) return;
      if (batchRun.finished < batchRun.total) {
        if (!batchRun.paused) setBatchStatus(`批量生成进度：${batchRun.finished}/${batchRun.total}，并发上限 ${MAX_BATCH_CONCURRENCY}。`);
        return;
      }
      batchQueueRunning = false;
      activeBatchRun = null;
      batchGenerateButton.disabled = false;
      batchPauseButton.disabled = true;
      const batchJobsList = [...batchRun.originalStates.keys()];
      const completed = batchJobsList.filter((item) => item.status === "complete").length;
      setBatchStatus(batchRun.paused
        ? `批量任务已暂停：${batchRun.total - batchRun.started} 个未提交；已开始的任务均已返回结果，${completed} 个生成成功。`
        : `批量任务结束：${completed}/${batchRun.total} 个生成成功。`);
    });
  });
});

batchPauseButton?.addEventListener("click", () => {
  if (!activeBatchRun) return;
  pauseBatchGeneration(activeBatchRun);
  batchPauseButton.disabled = true;
  setBatchStatus("已暂停批量生成：未发送和本地排队任务不会再提交；已开始的任务继续等待结果。");
});

batchDownloadButton?.addEventListener("click", async () => {
  const categoryLabel = BATCH_CATEGORY_LABELS[activeBatchCategory];
  const jobs = batchJobs[activeBatchCategory].filter((job) => job.result?.blob);
  if (!jobs.length) {
    setBatchStatus(`当前${categoryLabel}区没有可下载的图片。`);
    return;
  }
  try {
    const filenames = jobs.map(getBatchDownloadFilename);
    if (new Set(filenames.map((name) => name.toLowerCase())).size !== filenames.length) {
      throw new Error("当前分类存在重名图片，请先修改名称后再导出。");
    }
    if (typeof window.showDirectoryPicker === "function") {
      const directory = await window.showDirectoryPicker({
        id: `reference-atelier-${activeBatchCategory}`,
        mode: "readwrite",
        startIn: "pictures",
      });
      for (const job of jobs) {
        const fileHandle = await directory.getFileHandle(getBatchDownloadFilename(job), { create: true });
        const writable = await fileHandle.createWritable();
        await writable.write(job.result.blob);
        await writable.close();
      }
      setBatchStatus(`已将${categoryLabel}区 ${jobs.length} 张图片保存到所选文件夹。`);
    } else {
      for (const job of jobs) {
        downloadBatchJob(job);
        await sleep(120);
      }
      setBatchStatus(`当前浏览器不支持文件夹选择，已回退为逐张下载 ${jobs.length} 张${categoryLabel}区图片。`);
    }
  } catch (error) {
    if (error?.name === "AbortError") {
      setBatchStatus("已取消选择导出文件夹。");
      return;
    }
    setBatchStatus(`批量下载失败：${error.message}`);
  }
});

const refreshBatchMentionActiveOption = () => {
  batchMentionMenu.querySelectorAll(".batch-mention-option").forEach((option, index) => {
    option.classList.toggle("is-active", index === batchMentionState.activeIndex);
  });
};

const handleBatchMentionKeydown = (event) => {
  if (batchMentionMenu.hidden || batchMentionState.textarea !== event.target) return;
  if (event.key === "ArrowDown") {
    event.preventDefault();
    batchMentionState.activeIndex = (batchMentionState.activeIndex + 1) % batchMentionState.items.length;
    refreshBatchMentionActiveOption();
  } else if (event.key === "ArrowUp") {
    event.preventDefault();
    batchMentionState.activeIndex = (batchMentionState.activeIndex - 1 + batchMentionState.items.length) % batchMentionState.items.length;
    refreshBatchMentionActiveOption();
  } else if (event.key === "Enter") {
    event.preventDefault();
    chooseBatchMention(batchMentionState.items[batchMentionState.activeIndex]);
  } else if (event.key === "Escape") {
    event.preventDefault();
    closeBatchMentionMenu();
  }
};

