document.querySelector(".batch-board")?.addEventListener("click", (event) => {
  const card = event.target.closest("[data-batch-job-id]");
  const job = card ? getBatchJob(card.dataset.batchJobId) : null;
  if (!job) return;
  const previewRef = event.target.closest("[data-preview-batch-ref]");
  if (previewRef) {
    const ref = job.refs.find((item) => item.id === previewRef.dataset.previewBatchRef);
    if (!ref) return;
    previewTitle.textContent = `${job.nameInput.value.trim() || "当前任务"} · ${ref.mention}`;
    previewImage.src = ref.previewUrl;
    previewDialog.showModal();
    return;
  }
  const removeRefButton = event.target.closest("[data-remove-batch-ref]");
  if (removeRefButton) {
    const ref = job.refs.find((item) => item.id === removeRefButton.dataset.removeBatchRef);
    if (ref) URL.revokeObjectURL(ref.previewUrl);
    job.refs = job.refs.filter((item) => item !== ref);
    renderBatchReferences(job);
    schedulePersistBatchJob(job, true);
    return;
  }
  if (event.target.closest(".batch-generate-one")) {
    const operation = job.remoteTaskId ? queueBatchResume(job) : queueBatchGeneration(job);
    void operation.then((success) => {
      if (success) setBatchStatus(`“${job.nameInput.value.trim()}”生成完成，图片已保存到本地记录。`);
    });
    return;
  }
  if (event.target.closest(".batch-modify-button")) {
    void openBatchModifyDialog(job);
    return;
  }
  if (event.target.closest(".batch-download-one")) {
    try {
      const mode = downloadBatchJob(job);
      setBatchStatus(mode === "local" ? `已下载 ${getBatchDownloadFilename(job)}。` : "当前任务没有可下载的本地图片。");
    } catch (error) {
      setBatchStatus(`下载失败：${error.message}`);
    }
    return;
  }
  if (event.target.closest(".batch-favorite-button")) {
    void favoriteBatchJob(job);
    return;
  }
  if (event.target.closest(".batch-delete-button")) {
    if (removeBatchJob(job)) setBatchStatus("任务已删除。");
    return;
  }
  const historyButton = event.target.closest("[data-batch-history]");
  if (historyButton) {
    if (["running", "queued"].includes(job.status)) return;
    selectBatchResult(job, job.resultIndex + (historyButton.dataset.batchHistory === "previous" ? -1 : 1));
    return;
  }
  const image = event.target.closest("[data-batch-preview]");
  if (image) {
    previewTitle.textContent = `${job.nameInput.value.trim() || "生成结果"} · ${job.resultIndex + 1}/${job.results.length}`;
    previewImage.src = job.result.objectUrl;
    previewDialog.showModal();
  }
});

const optimizeInternalReferenceFile = async (blob, jobId) => {
  const fallbackType = blob.type || "image/png";
  const fallbackExtension = fallbackType.includes("jpeg") ? "jpg" : fallbackType.includes("webp") ? "webp" : "png";
  const fallbackFile = new File([blob], `internal-reference-${jobId}.${fallbackExtension}`, { type: fallbackType });
  if (typeof createImageBitmap !== "function") return { file: fallbackFile, optimized: false };

  let bitmap;
  try {
    bitmap = await createImageBitmap(blob);
    const maxEdge = 2048;
    const scale = Math.min(1, maxEdge / Math.max(bitmap.width, bitmap.height));
    if (scale === 1 && blob.size <= 800 * 1024) return { file: fallbackFile, optimized: false };
    const canvas = document.createElement("canvas");
    canvas.width = Math.max(1, Math.round(bitmap.width * scale));
    canvas.height = Math.max(1, Math.round(bitmap.height * scale));
    const context = canvas.getContext("2d", { alpha: false });
    context.fillStyle = "#ffffff";
    context.fillRect(0, 0, canvas.width, canvas.height);
    context.drawImage(bitmap, 0, 0, canvas.width, canvas.height);
    const optimizedBlob = await new Promise((resolve) => canvas.toBlob(resolve, "image/jpeg", 0.9));
    if (!optimizedBlob || optimizedBlob.size >= blob.size) return { file: fallbackFile, optimized: false };
    return {
      file: new File([optimizedBlob], `internal-reference-${jobId}.jpg`, { type: "image/jpeg" }),
      optimized: true,
    };
  } catch {
    return { file: fallbackFile, optimized: false };
  } finally {
    bitmap?.close?.();
  }
};

closeBatchModifyButton?.addEventListener("click", closeBatchModifyDialog);
cancelBatchModifyButton?.addEventListener("click", closeBatchModifyDialog);
batchModifyDialog?.addEventListener("close", () => {
  modifyingBatchJobId = "";
});
batchModifyForm?.addEventListener("submit", async (event) => {
  event.preventDefault();
  const job = getBatchJob(modifyingBatchJobId);
  const modifyPrompt = batchModifyPrompt.value.trim();
  const sourceBlob = job?.result?.blob;
  if (!job?.result || !(sourceBlob instanceof Blob) || !modifyPrompt) {
    batchModifyPrompt.focus();
    return;
  }
  const connectionId = job.connectionId || activeConnectionId;
  const connection = connectionProfiles.find((item) => item.id === connectionId);
  const options = { ...(job.lastOptions || getBatchOptions()), endpoint: connection?.endpoint || job.lastOptions?.endpoint };
  closeBatchModifyDialog();
  setBatchStatus(`正在优化“${job.nameInput.value.trim()}”的内部参考图，减少上传等待时间…`);
  const preparedReference = await optimizeInternalReferenceFile(sourceBlob, job.id);
  const internalReference = {
    file: preparedReference.file,
    id: `internal-${job.id}`,
    mention: "内部原图",
  };
  const sizeDetail = preparedReference.optimized
    ? `，上传体积已由 ${formatBytes(sourceBlob.size)} 压缩到 ${formatBytes(preparedReference.file.size)}`
    : "";
  setBatchStatus(`正在原位修改“${job.nameInput.value.trim()}”，当前图片仅作为本次内部参考${sizeDetail}。`);
  const success = await queueBatchGeneration(job, {
    apiKey: connection?.apiKey,
    connectionId,
    internalReference,
    modifyPrompt,
    options,
  });
  if (success) setBatchStatus(`“${job.nameInput.value.trim()}”已在原位置修改完成。`);
});

const initializeBatchWorkspace = async () => {
  renderBatchModelOptions();
  Object.keys(batchJobs).forEach(renderBatchEmptyState);
  try {
    await loadDraftsAndMigrateLegacyWorkspace();
    draftsHome.hidden = false;
    batchWorkspace.hidden = true;
  } catch (error) {
    drafts = [];
    renderDrafts();
    setDraftsStatus(`草稿列表恢复失败：${error?.message || error}`);
  }
};

previewDialog.addEventListener("close", () => {
  previewImage.removeAttribute("src");
});

window.addEventListener("beforeunload", () => {
  persistGenerationSettings();
  persistPromptDraft();
  references.forEach((ref) => URL.revokeObjectURL(ref.previewUrl));
  finishedImages.forEach((image) => {
    if (image.objectUrl) URL.revokeObjectURL(image.objectUrl);
  });
  Object.values(batchJobs).flat().forEach((job) => {
    job.refs.forEach((ref) => URL.revokeObjectURL(ref.previewUrl));
    releaseBatchJobResults(job);
  });
  Object.values(batchGlobalReferences).flat().forEach((ref) => URL.revokeObjectURL(ref.previewUrl));
});

const initializeApp = async () => {
  loadConnections();
  renderConnectionPicker();
  restoreGenerationState();
  await initializeBatchWorkspace();
  try {
    await restoreReferences();
    renderReferences();
    setStatus(references.length ? `已恢复 ${references.length} 张本地参考图。` : "等待输入");
  } catch (error) {
    renderReferences();
    setStatus(`本地参考图恢复失败：${error?.message || error}`);
  }
};

void initializeApp();

