}

.result-zone {
  min-width: 0;
  position: relative;
}

.empty-state {
  min-height: calc(100vh - 170px);
  display: grid;
  place-items: center;
  align-content: center;
  justify-items: center;
  gap: 12px;
  color: #65727a;
  text-align: center;
}

.empty-mark {
  width: 98px;
  height: 98px;
  display: grid;
  place-items: center;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: linear-gradient(180deg, #ffffff, #edf2f1);
  color: #718087;
}

.empty-mark svg {
  width: 48px;
  height: 48px;
}

.empty-state h1 {
  margin: 8px 0 0;
  color: #202a30;
  font-size: 24px;
  letter-spacing: 0;
}

.empty-state p {
  margin: 0;
  max-width: 320px;
  line-height: 1.55;
}

.result-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
  gap: 14px;
}

.result-card {
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.96);
  box-shadow: 0 14px 32px rgba(25, 38, 45, 0.08);
}

.result-visual {
  width: 100%;
  aspect-ratio: 1 / 1;
  display: grid;
  place-items: center;
  background: linear-gradient(135deg, rgba(22, 122, 127, 0.05), rgba(196, 107, 40, 0.05)), #f5f7f7;
}

.result-visual img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.placeholder {
  display: grid;
  justify-items: center;
  gap: 8px;
  padding: 18px;
  color: var(--muted);
  text-align: center;
}

.placeholder strong {
  color: #202a30;
}

.placeholder small {
  max-width: 100%;
  line-height: 1.45;
  overflow-wrap: anywhere;
}

.result-card.is-error {
  border-color: rgba(189, 63, 74, 0.45);
}

.result-card.is-error .result-visual {
  background: #fff5f6;
}

.spinner {
  width: 28px;
  height: 28px;
  border: 3px solid #d5e0df;
  border-top-color: var(--teal);
  border-radius: 999px;
  animation: spin 800ms linear infinite;
}

@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}

.result-meta {
  padding: 9px 10px;
  border-top: 1px solid #e6eceb;
  color: var(--muted);
  font-size: 12px;
}

.result-meta strong,
.result-meta span {
  display: block;
  overflow-wrap: anywhere;
}

.result-meta strong {
  color: #26313a;
  font-size: 13px;
}

.result-meta span {
  margin-top: 4px;
  line-height: 1.45;
}

.result-actions {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 8px;
  padding: 10px;
  border-top: 1px solid #e6eceb;
}

.result-card.is-running .edit-task-button,
.result-card.is-error .edit-task-button {
  grid-column: 1 / -1;
}

.edit-task-button:not(:disabled) {
  color: var(--teal);
  border-color: rgba(22, 122, 127, 0.28);
  background: #f2fbfa;
}

.favorite-button:not(:disabled) {
  color: #8a4c15;
  background: #fff9f3;
}

.favorite-button:disabled {
  cursor: default;
  color: var(--green);
  border-color: rgba(23, 115, 79, 0.25);
  background: #eff8f3;
}

.small-button {
  min-height: 32px;
  display: inline-grid;
  place-items: center;
  padding: 0 10px;
  color: #243037;
  border-color: var(--line);
  background: #ffffff;
  text-decoration: none;
  font-size: 12px;
}

.small-button:disabled {
  cursor: wait;
  color: #8a969c;
  background: #f3f6f5;
}

.tool-panel {
  padding: 20px 16px 16px;
  overflow: auto;
}

.upload-box {
  position: relative;
  min-height: 214px;
  display: grid;
  place-items: center;
  align-content: center;
  gap: 14px;
  overflow: hidden;
  border: 2px dashed rgba(22, 122, 127, 0.42);
  border-radius: 8px;
  color: #435159;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.74), rgba(243, 247, 246, 0.78));
}

.upload-box:hover,
.upload-box.is-dragging {
  border-color: var(--orange);
  background: #fffefd;
}

.page-drop-overlay {
  position: fixed;
  inset: 12px;
  z-index: 100;
  display: grid;
  place-items: center;
  border: 3px dashed rgba(22, 122, 127, 0.7);
  border-radius: 16px;
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  color: #114f53;
  background: rgba(239, 249, 248, 0.92);
  backdrop-filter: blur(8px);
  transition: opacity 120ms ease, visibility 120ms ease;
}

body.is-page-dragging .page-drop-overlay {
  opacity: 1;
  visibility: visible;
}

.page-drop-card {
  min-width: min(420px, calc(100vw - 56px));
  display: grid;
  place-items: center;
  gap: 10px;
  padding: 34px;
  border: 1px solid rgba(22, 122, 127, 0.18);
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.92);
  box-shadow: 0 24px 70px rgba(22, 74, 77, 0.18);
}

.page-drop-card strong {
  font-size: 22px;
}

.page-drop-card > span:last-child {
  color: var(--muted);
  font-size: 13px;
}

.upload-box input {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  opacity: 0;
  cursor: pointer;
}

.upload-box strong {
  color: var(--teal);
  font-size: 18px;
}

.upload-box small {
  color: var(--muted);
}

.upload-icon {
  color: var(--teal);
}

.upload-icon svg {
  width: 36px;
  height: 36px;
}

.model-row {
  margin-top: 18px;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}

.model-row.has-resolution {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.field,
.model-row label {
  display: grid;
  gap: 8px;
}

.field {
  margin-top: 12px;
}

.field > span,
.model-row span {
  color: #233038;
  font-size: 13px;
  font-weight: 800;
}

select,
input,
textarea {
  width: 100%;
  border: 1px solid var(--line-strong);
  border-radius: 8px;
  outline: none;
  background: #f7faf9;
  color: #1b252b;
}

select,
input {
  height: 38px;
  padding: 0 12px;
}

select {
  appearance: none;
  background-image:
    linear-gradient(45deg, transparent 50%, #738087 50%),
    linear-gradient(135deg, #738087 50%, transparent 50%);
  background-position:
    calc(100% - 18px) 16px,
    calc(100% - 13px) 16px;
  background-repeat: no-repeat;
  background-size: 5px 5px;
}

textarea {
  min-height: 150px;
  display: block;
  padding: 12px;
  line-height: 1.55;
  resize: vertical;
}

select:focus,
input:focus,
textarea:focus {
  border-color: var(--orange);
  box-shadow: 0 0 0 3px rgba(196, 107, 40, 0.14);
  background: #ffffff;
}

.prompt-wrap {
  position: relative;
}

.mention-menu {
  position: absolute;
  left: 8px;
  right: 8px;
  bottom: calc(100% - 6px);
  z-index: 8;
  max-height: 280px;
  overflow: auto;
  padding: 8px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 8px;
  background: rgba(18, 23, 28, 0.98);
  box-shadow: 0 22px 60px rgba(18, 23, 28, 0.28);
}

.mention-title {
  padding: 4px 6px 8px;
  color: #aeb8c5;
  font-size: 12px;
}

.mention-option {
  width: 100%;
  min-height: 50px;
  display: grid;
  grid-template-columns: 36px minmax(0, 1fr) auto;
  align-items: center;
  gap: 8px;
  padding: 6px;
  border: 0;
  border-radius: 6px;
  color: #eaf2fb;
  background: transparent;
  text-align: left;
}

.mention-option:hover,
.mention-option.is-active {
  background: rgba(196, 107, 40, 0.28);
}

.mention-option img {
  width: 36px;
  height: 36px;
  border-radius: 6px;
  object-fit: cover;
}

.mention-option strong,
.mention-option small {
  display: block;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.mention-option small {
  margin-top: 2px;
  color: #b8c3c8;
  font-size: 12px;
}

.mention-badge {
  min-height: 24px;
  display: inline-flex;
  align-items: center;
  padding: 0 8px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.12);
  color: #f4d1b2;
  font-size: 12px;
  font-weight: 800;
}

.mention-bar {
  min-height: 28px;
  margin-top: 10px;
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  align-items: center;
  color: var(--muted);
  font-size: 12px;
  line-height: 1.4;
}

.chip {
  min-height: 26px;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 0 8px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: #ffffff;
  color: #59666e;
  font-weight: 700;
}

.chip img {
  width: 22px;
  height: 22px;
  margin-left: -5px;
  border-radius: 999px;
  object-fit: cover;
}

.chip.bound {
  color: #905017;
  background: #ffe2c8;
  border-color: rgba(196, 107, 40, 0.35);
}

.chip.missing {
  color: var(--red);
  background: #ffe8ea;
  border-color: rgba(189, 63, 74, 0.3);
}

.generate-button {
  width: 100%;
  min-height: 50px;
  margin-top: 18px;
  font-size: 16px;
}

.generate-button:disabled {
  opacity: 0.72;
  cursor: not-allowed;
  transform: none;
}

.status-line {
  min-height: 22px;
  margin-top: 12px;
  color: var(--muted);
  font-size: 13px;
  line-height: 1.45;
  text-align: center;
  overflow-wrap: anywhere;
}

.icon-button {
  width: 36px;
  height: 36px;
  display: inline-grid;
  place-items: center;
  padding: 0;
  color: #526169;
  border-color: var(--line);
  background: #ffffff;
}

.icon-button svg {
  width: 18px;
  height: 18px;
}

.settings-dialog,
.preview-dialog {
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 0;
  color: var(--ink);
  background: #ffffff;
  box-shadow: 0 28px 70px rgba(18, 23, 28, 0.24);
}

.settings-dialog {
  width: min(520px, calc(100vw - 32px));
}

.settings-dialog::backdrop,
.preview-dialog::backdrop {
  background: rgba(18, 23, 28, 0.36);
}

.settings-card {
  padding: 16px;
  display: grid;
  gap: 18px;
}

.dialog-head,
.preview-head {
  display: flex;
  align-items: start;
  justify-content: space-between;
  gap: 14px;
}

.dialog-head strong,
.dialog-head span {
  display: block;
}

.dialog-head strong {
  font-size: 18px;
}

.dialog-head span {
  margin-top: 4px;
  color: var(--muted);
  font-size: 13px;
  line-height: 1.45;
}

.settings-note {
  margin: -2px 0 0;
  padding: 10px 12px;
  border-radius: 8px;
  color: var(--muted);
  background: #f3f7f6;
  font-size: 12px;
  line-height: 1.55;
}

.preview-dialog {
  width: min(1120px, calc(100vw - 28px));
  max-height: calc(100vh - 28px);
  overflow: hidden;
}

.preview-head {
  min-height: 50px;
  align-items: center;
  padding: 8px 10px 8px 14px;
  border-bottom: 1px solid #e6eceb;
}

.preview-head strong {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.preview-dialog img {
  width: 100%;
  max-height: calc(100vh - 86px);
  display: block;
  object-fit: contain;
  background: #f3f6f5;
}

/* Draft hub */
.drafts-home {
  width: min(1500px, calc(100% - 40px));
  min-height: calc(100vh - 100px);
  margin: 20px auto;
}

.drafts-hero {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(320px, 430px);
  align-items: stretch;
  gap: 22px;
  padding: 28px;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: linear-gradient(135deg, rgba(255,255,255,.98), rgba(237,247,245,.96));
  box-shadow: 0 18px 48px rgba(21, 35, 42, 0.08);
}

.drafts-eyebrow {
  color: var(--teal);
  font-size: 12px;
  font-weight: 900;
  letter-spacing: .14em;
}

.drafts-hero h1 {
  margin: 10px 0 8px;
  font-size: clamp(28px, 4vw, 46px);
  letter-spacing: -.04em;
}

.drafts-hero p {
  max-width: 720px;
  margin: 0;
  color: var(--muted);
  line-height: 1.75;
}

.new-draft-button {
  min-height: 150px;
  display: grid;
  grid-template-columns: 58px 1fr;
  grid-template-rows: auto auto;
  align-content: center;
  gap: 2px 14px;
  padding: 22px;
  border: 1px solid rgba(22, 122, 127, .28);
  border-radius: 16px;
  color: #fff;
  text-align: left;
  background: linear-gradient(135deg, #167a7f, #105d63);
  box-shadow: 0 16px 34px rgba(22, 122, 127, .24);
}

.new-draft-button > span {
  grid-row: 1 / 3;
  align-self: center;
  font-size: 48px;
  font-weight: 300;
  line-height: 1;
}

.new-draft-button strong {
  align-self: end;
  font-size: 22px;
}

.new-draft-button small {
  align-self: start;
  color: rgba(255,255,255,.78);
  font-size: 12px;
}

.new-draft-button:hover {
  transform: translateY(-2px);
  box-shadow: 0 20px 42px rgba(22, 122, 127, .3);
}

.drafts-section {
  margin-top: 18px;
  padding: 20px;
  border: 1px solid var(--line);
  border-radius: 16px;
  background: rgba(255,255,255,.94);
  box-shadow: var(--shadow);
}

.drafts-section-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  margin-bottom: 16px;
}

.drafts-section-head > div {
  display: flex;
  align-items: baseline;
  gap: 12px;
}

.drafts-section-head h2 {
  margin: 0;
  font-size: 20px;
}

.drafts-section-head span,
.drafts-status {
  color: var(--muted);
  font-size: 12px;
}

.drafts-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(350px, 1fr));
  gap: 14px;
}

.draft-card {
  min-width: 0;
  display: grid;
  grid-template-columns: 52px minmax(0, 1fr);
  gap: 12px;
  padding: 16px;
  border: 1px solid var(--line);
  border-radius: 13px;
  background: #fff;
  box-shadow: 0 10px 26px rgba(21, 35, 42, .06);
}

.draft-card-mark {
  width: 52px;
  height: 52px;
  display: grid;
  place-items: center;
  border-radius: 13px;
  color: #fff;
  background: linear-gradient(135deg, #26323a, #151b20);
  font-size: 20px;
  font-weight: 900;
}

.draft-card-copy {
  min-width: 0;
  display: grid;
  gap: 6px;
}

.draft-name-input {
  min-width: 0;
  height: 38px;
  padding: 0 10px;
  font-size: 15px;
  font-weight: 900;
}

.draft-card-copy span {
  color: var(--muted);
  font-size: 11px;
}

.draft-card-actions {
  grid-column: 1 / -1;
  display: flex;
  gap: 8px;
  justify-content: flex-end;
  padding-top: 10px;
  border-top: 1px solid var(--line);
}

.draft-card-actions button {
  min-height: 36px;
}

.drafts-empty {
  min-height: 260px;
  display: grid;
  place-items: center;
  align-content: center;
  gap: 8px;
  color: var(--muted);
  border: 1px dashed var(--line-strong);
  border-radius: 12px;
}

.drafts-empty strong {
  color: var(--ink);
  font-size: 18px;
}

.draft-dialog {
  width: min(520px, calc(100vw - 32px));
}

/* Batch image workspace */
.batch-workspace {
  min-height: calc(100vh - 76px);
  display: grid;
  grid-template-rows: auto auto auto 1fr auto;
  gap: 12px;
  padding: 16px 20px 20px;
}

.batch-command-bar,
.batch-toolbar,
.batch-global-prompt-bar,
.batch-board,
.batch-status {
  border: 1px solid var(--line);
  background: rgba(255, 255, 255, 0.94);
  box-shadow: var(--shadow);
}

.batch-global-prompt-bar {
  display: grid;
  grid-template-columns: minmax(210px, 0.25fr) minmax(360px, 1fr) minmax(250px, 0.42fr);
  align-items: center;
  gap: 16px;
  padding: 10px 14px;
  border-radius: 12px;
}

.batch-global-prompt-bar strong,
.batch-global-prompt-bar span {
  display: block;
}

.batch-global-prompt-bar strong {
  font-size: 14px;
}

.batch-global-prompt-bar span {
  margin-top: 4px;
  color: var(--muted);
  font-size: 11px;
}

.batch-global-prompt-bar textarea {
  min-height: 58px;
  resize: vertical;
}

.batch-global-reference-section {
  min-width: 0;
  padding-left: 14px;
  border-left: 1px solid var(--line);
}

.batch-global-reference-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 7px;
}

.batch-global-reference-head strong {
  font-size: 12px;
}

.batch-global-reference-head span {
  margin: 0;
}

.batch-global-reference-list {
  display: flex;
  gap: 7px;
  overflow-x: auto;
  padding: 3px;
  border: 1px dashed transparent;
  border-radius: 9px;
  transition: border-color 120ms ease, background 120ms ease, box-shadow 120ms ease;
}

.batch-global-reference-list.is-dragging {
  border-color: var(--teal);
  background: rgba(22, 122, 127, 0.08);
  box-shadow: inset 0 0 0 2px rgba(22, 122, 127, 0.1);
}

.batch-global-reference-upload,
.batch-global-reference-thumb {
  width: 58px;
  height: 58px;
  flex: 0 0 58px;
  border-radius: 8px;
}

.batch-global-reference-upload {
  display: grid;
  place-items: center;
  border: 1px dashed var(--line-strong);
  color: var(--teal);
  background: #f6fbfa;
  font-size: 22px;
  cursor: pointer;
}

.batch-global-reference-upload input {
  display: none;
}

.batch-global-reference-thumb {
  position: relative;
  overflow: hidden;
  border: 1px solid var(--line);
  background: #edf1f0;
}

.batch-global-reference-thumb img {
  width: 100%;
  height: 100%;
  display: block;
  object-fit: cover;
  cursor: zoom-in;
}

.batch-global-reference-tag {
  position: absolute;
  left: 3px;
  bottom: 3px;
  max-width: calc(100% - 6px);
  overflow: hidden;
  padding: 2px 4px;
  border-radius: 4px;
  color: #fff;
  background: rgba(15, 24, 28, 0.78);
  font-size: 9px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.batch-global-reference-remove {
  position: absolute;
  top: 2px;
  right: 2px;
  width: 19px;
  height: 19px;
  display: grid;
  place-items: center;
  padding: 0;
  border: 0;
  border-radius: 50%;
  color: #fff;
  background: rgba(16, 23, 27, 0.82);
  font-size: 12px;
}

.batch-mention-menu {
  position: fixed;
  z-index: 80;
  width: min(330px, calc(100vw - 24px));
  max-height: 250px;
  overflow: auto;
  padding: 6px;
  border: 1px solid var(--line-strong);
  border-radius: 10px;
  background: #fff;
  box-shadow: 0 18px 46px rgba(18, 23, 28, 0.22);
}

.batch-mention-option {
  width: 100%;
  min-height: 48px;
  display: grid;
  grid-template-columns: 38px minmax(0, 1fr);
  align-items: center;
  gap: 9px;
  padding: 5px 7px;
  border: 0;
  border-radius: 7px;
  color: var(--ink);
  background: transparent;
  text-align: left;
}

.batch-mention-option:hover,
.batch-mention-option.is-active {
  background: #edf7f6;
}

.batch-mention-option img {
  width: 38px;
  height: 38px;
  border-radius: 6px;
  object-fit: cover;
}

.batch-mention-option strong,
.batch-mention-option small {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.batch-mention-option small {
  margin-top: 2px;
  color: var(--muted);
}

.batch-command-bar {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 20px;
  padding: 14px 16px;
  border-radius: 12px;
}

.batch-command-title {
  display: flex;
  align-items: center;
  gap: 14px;
}

.draft-back-button {
  min-height: 38px;
  padding: 0 12px;
  border-color: var(--line);
  color: var(--teal);
  background: #f3f9f8;
  font-weight: 800;
}

.batch-command-title strong,
.batch-command-title span {
  display: block;
}

.batch-command-title strong {
