const DATABASE_NAME = "reference-atelier-storage";
const REFERENCE_STORE = "reference-images";
const FAVORITE_STORE = "favorite-images";
const BATCH_STORE = "batch-workspace";

const favoritesGrid = document.querySelector("#favoritesGrid");
const favoritesEmpty = document.querySelector("#favoritesEmpty");
const favoriteCount = document.querySelector("#favoriteCount");
const favoritesStatus = document.querySelector("#favoritesStatus");
const clearFavoritesButton = document.querySelector("#clearFavoritesButton");
const previewDialog = document.querySelector("#favoritePreviewDialog");
const previewTitle = document.querySelector("#favoritePreviewTitle");
const previewImage = document.querySelector("#favoritePreviewImage");

let favorites = [];
let databasePromise = null;
const objectUrls = new Map();

const escapeHtml = (value) =>
  String(value ?? "").replace(/[&<>"']/g, (char) => ({
    "&": "&amp;",
    "<": "&lt;",
    ">": "&gt;",
    '"': "&quot;",
    "'": "&#39;",
  })[char]);

const setStatus = (message) => {
  favoritesStatus.textContent = message;
};

const openDatabase = () => {
  if (!window.indexedDB) {
    return Promise.reject(new Error("当前浏览器不支持 IndexedDB。"));
  }
  if (!databasePromise) {
    databasePromise = new Promise((resolve, reject) => {
      const request = indexedDB.open(DATABASE_NAME);
      request.onupgradeneeded = () => {
        const database = request.result;
        if (!database.objectStoreNames.contains(REFERENCE_STORE)) {
          database.createObjectStore(REFERENCE_STORE, { keyPath: "position" });
        }
        if (!database.objectStoreNames.contains(FAVORITE_STORE)) {
          database.createObjectStore(FAVORITE_STORE, { keyPath: "id" });
        }
        if (!database.objectStoreNames.contains(BATCH_STORE)) {
          database.createObjectStore(BATCH_STORE, { keyPath: "key" });
        }
      };
      request.onsuccess = () => {
        request.result.onversionchange = () => request.result.close();
        resolve(request.result);
      };
      request.onerror = () => reject(request.error || new Error("无法打开本地收藏存储。"));
      request.onblocked = () => reject(new Error("本地存储正在被旧页面占用，请关闭旧页面后重试。"));
    });
  }
  return databasePromise;
};

const waitForTransaction = (transaction) => new Promise((resolve, reject) => {
  transaction.oncomplete = () => resolve();
  transaction.onerror = () => reject(transaction.error || new Error("本地收藏操作失败。"));
  transaction.onabort = () => reject(transaction.error || new Error("本地收藏操作已中止。"));
});

const clearObjectUrls = () => {
  objectUrls.forEach((url) => URL.revokeObjectURL(url));
  objectUrls.clear();
};

const formatDate = (timestamp) => new Intl.DateTimeFormat("zh-CN", {
  dateStyle: "medium",
  timeStyle: "short",
}).format(new Date(timestamp));

const renderFavoritePrompt = (promptValue) => {
  const prompt = String(promptValue || "未保存提示词");
  const isLong = prompt.length > 180 || prompt.split(/\r?\n/).length > 4;
  const content = `<p class="favorite-prompt">${escapeHtml(prompt)}</p>`;
  return isLong
    ? `<details class="favorite-prompt-details"><summary>展开完整提示词</summary>${content}</details>`
    : content;
};

const renderFavorites = () => {
  clearObjectUrls();
  favoritesGrid.innerHTML = "";
  favoriteCount.textContent = `${favorites.length} 项`;
  favoritesEmpty.hidden = favorites.length > 0;
  clearFavoritesButton.disabled = favorites.length === 0;

  favorites.forEach((favorite) => {
    const imageUrl = URL.createObjectURL(favorite.blob);
    objectUrls.set(favorite.id, imageUrl);
    const card = document.createElement("article");
    card.className = "favorite-card";
    card.dataset.favoriteId = favorite.id;
    card.innerHTML = `
      <button class="favorite-image-button" type="button" data-preview-favorite="${escapeHtml(favorite.id)}" title="预览图片">
        <img src="${imageUrl}" alt="收藏图片" />
      </button>
      <div class="favorite-copy">
        <div class="favorite-meta">
          <span>${escapeHtml(favorite.model || "未知模型")}</span>
          <span>${escapeHtml(favorite.size || "未知比例")}</span>
          <span>${escapeHtml(formatDate(favorite.createdAt))}</span>
        </div>
        ${renderFavoritePrompt(favorite.prompt)}
      </div>
      <div class="favorite-actions">
        <button class="small-button" type="button" data-copy-favorite="${escapeHtml(favorite.id)}">复制提示词</button>
        <button class="small-button" type="button" data-download-favorite="${escapeHtml(favorite.id)}">下载</button>
        <button class="small-button danger" type="button" data-delete-favorite="${escapeHtml(favorite.id)}">删除</button>
      </div>
    `;
    favoritesGrid.append(card);
  });
};

const loadFavorites = async () => {
  const database = await openDatabase();
  const transaction = database.transaction(FAVORITE_STORE, "readonly");
  const request = transaction.objectStore(FAVORITE_STORE).getAll();
  const records = await new Promise((resolve, reject) => {
    request.onsuccess = () => resolve(request.result || []);
    request.onerror = () => reject(request.error || new Error("无法读取本地收藏。"));
  });
  favorites = records
    .filter((record) => record.blob instanceof Blob)
    .sort((left, right) => right.createdAt - left.createdAt);
  renderFavorites();
  setStatus(favorites.length ? `已读取 ${favorites.length} 项本地收藏` : "暂无收藏");
};

const findFavorite = (id) => favorites.find((favorite) => favorite.id === id);

const copyPrompt = async (prompt) => {
  try {
    await navigator.clipboard.writeText(prompt);
  } catch {
    const textarea = document.createElement("textarea");
    textarea.value = prompt;
    textarea.style.position = "fixed";
    textarea.style.opacity = "0";
    document.body.append(textarea);
    textarea.select();
    document.execCommand("copy");
    textarea.remove();
  }
  setStatus("提示词已复制");
};

const downloadFavorite = (favorite) => {
  const link = document.createElement("a");
  link.href = objectUrls.get(favorite.id) || URL.createObjectURL(favorite.blob);
  link.download = favorite.filename || `favorite-${favorite.createdAt}.png`;
  link.click();
};

const deleteFavorite = async (favorite) => {
  if (!window.confirm("确定删除这项收藏吗？")) return;
  const database = await openDatabase();
  const transaction = database.transaction(FAVORITE_STORE, "readwrite");
  transaction.objectStore(FAVORITE_STORE).delete(favorite.id);
  await waitForTransaction(transaction);
  favorites = favorites.filter((item) => item.id !== favorite.id);
  renderFavorites();
  setStatus("收藏已删除");
};

const clearFavorites = async () => {
  if (!favorites.length || !window.confirm("确定清空全部收藏图片和提示词吗？")) return;
  const database = await openDatabase();
  const transaction = database.transaction(FAVORITE_STORE, "readwrite");
  transaction.objectStore(FAVORITE_STORE).clear();
  await waitForTransaction(transaction);
  favorites = [];
  renderFavorites();
  setStatus("全部收藏已清空");
};

favoritesGrid.addEventListener("click", (event) => {
  const previewButton = event.target.closest("[data-preview-favorite]");
  if (previewButton) {
    const favorite = findFavorite(previewButton.dataset.previewFavorite);
    if (!favorite) return;
    previewTitle.textContent = favorite.title || "收藏图片";
    previewImage.src = objectUrls.get(favorite.id);
    previewDialog.showModal();
    return;
  }

  const copyButton = event.target.closest("[data-copy-favorite]");
  if (copyButton) {
    const favorite = findFavorite(copyButton.dataset.copyFavorite);
    if (favorite) void copyPrompt(favorite.prompt || "");
    return;
  }

  const downloadButton = event.target.closest("[data-download-favorite]");
  if (downloadButton) {
    const favorite = findFavorite(downloadButton.dataset.downloadFavorite);
    if (favorite) downloadFavorite(favorite);
    return;
  }

  const deleteButton = event.target.closest("[data-delete-favorite]");
  if (deleteButton) {
    const favorite = findFavorite(deleteButton.dataset.deleteFavorite);
    if (favorite) void deleteFavorite(favorite).catch((error) => setStatus(`删除失败：${error?.message || error}`));
  }
});

clearFavoritesButton.addEventListener("click", () => {
  void clearFavorites().catch((error) => setStatus(`清空失败：${error?.message || error}`));
});

previewDialog.addEventListener("close", () => {
  previewImage.removeAttribute("src");
});

document.addEventListener("visibilitychange", () => {
  if (document.visibilityState === "visible") {
    void loadFavorites().catch((error) => setStatus(`读取收藏失败：${error?.message || error}`));
  }
});

window.addEventListener("beforeunload", clearObjectUrls);

void loadFavorites().catch((error) => {
  renderFavorites();
  setStatus(`读取收藏失败：${error?.message || error}`);
});

