  min-height: 100vh;
}

.favorites-main-link {
  min-height: 36px;
  display: inline-flex;
  align-items: center;
  padding: 0 16px;
  text-decoration: none;
}

.favorites-shell {
  width: min(1480px, calc(100% - 44px));
  margin: 0 auto;
  padding-bottom: 36px;
}

.favorites-toolbar {
  min-height: 72px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  padding: 14px 16px;
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
}

.favorites-toolbar > div {
  min-width: 0;
  display: flex;
  align-items: baseline;
  gap: 12px;
}

.favorites-toolbar h1 {
  margin: 0;
  font-size: 20px;
  letter-spacing: 0;
}

.favorites-toolbar span,
.favorites-status {
  color: var(--muted);
  font-size: 12px;
}

.favorites-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 16px;
  padding: 18px 0;
}

.favorite-card {
  min-width: 0;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.96);
  box-shadow: 0 14px 32px rgba(25, 38, 45, 0.08);
}

.favorite-image-button {
  width: 100%;
  aspect-ratio: 1 / 1;
  display: block;
  padding: 0;
  overflow: hidden;
  border: 0;
  border-radius: 0;
  background: #eef2f1;
}

.favorite-image-button img {
  width: 100%;
  height: 100%;
  display: block;
  object-fit: contain;
}

.favorite-copy {
  min-height: 138px;
  padding: 13px 14px;
  border-top: 1px solid var(--line);
}

.favorite-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 6px 10px;
  color: var(--muted);
  font-size: 11px;
}

.favorite-prompt {
  margin: 10px 0 0;
  color: #26313a;
  line-height: 1.65;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  font-size: 13px;
}

.favorite-prompt-details {
  margin-top: 10px;
}

.favorite-prompt-details summary {
  width: fit-content;
  color: var(--teal);
  font-size: 12px;
  font-weight: 800;
  cursor: pointer;
  user-select: none;
}

.favorite-prompt-details .favorite-prompt {
  max-height: 260px;
  overflow: auto;
  padding: 9px 10px;
  border-radius: 6px;
  background: #f5f8f7;
}

.favorite-actions {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
  padding: 10px;
  border-top: 1px solid var(--line);
}

.favorite-actions .danger {
  color: var(--red);
}

.favorites-empty {
  min-height: calc(100vh - 230px);
  display: grid;
  place-items: center;
  align-content: center;
  justify-items: center;
  gap: 11px;
  color: var(--muted);
  text-align: center;
}

.favorites-empty strong {
  color: #26313a;
  font-size: 18px;
}

.favorites-status {
  position: fixed;
  right: 18px;
  bottom: 14px;
  max-width: calc(100vw - 36px);
  padding: 7px 10px;
  border: 1px solid var(--line);
  border-radius: 6px;
  background: rgba(255, 255, 255, 0.94);
  box-shadow: 0 8px 22px rgba(25, 38, 45, 0.08);
}

@media (max-width: 720px) {
  .favorites-shell {
    width: min(100% - 24px, 1480px);
  }

  .favorites-toolbar {
    align-items: flex-start;
    padding-inline: 0;
  }

  .favorites-toolbar > div {
    display: grid;
    gap: 4px;
  }

  .favorites-grid {
    grid-template-columns: 1fr;
  }
}

(() => {
  "use strict";
  const FILES = ["index.html", "app.js", "styles.css", "favorites.html", "favorites.js", "favorites.css", "updater.js", "update-source.js"];
  const compareVersions = (left, right) => {
    const a = left.split(".").map(Number);
    const b = right.split(".").map(Number);
    for (let index = 0; index < 3; index += 1) {
      if (a[index] !== b[index]) return a[index] > b[index] ? 1 : -1;
    }
    return 0;
  };
  const validatePackage = async (release, digest) => {
    if (release?.app !== "reference-atelier" || release.format !== 1 || !/^\d+\.\d+\.\d+$/.test(release.version || "")) {
      throw new Error("更新包格式不正确。");
    }
    if (!Array.isArray(release.files) || release.files.length !== FILES.length) throw new Error("更新包文件不完整。");
    const names = new Set();
    for (const file of release.files) {
      if (!FILES.includes(file.name) || names.has(file.name) || typeof file.content !== "string" || !/^[a-f0-9]{64}$/.test(file.sha256 || "")) {
        throw new Error("更新包包含不允许替换的文件。");
      }
      names.add(file.name);
      if (await digest(file.content) !== file.sha256) throw new Error(`文件校验失败：${file.name}`);
    }
    return release;
  };
  const writeFile = async (directory, name, content) => {
    const handle = await directory.getFileHandle(name, { create: true });
    const writable = await handle.createWritable();
    try {
      await writable.write(content);
      await writable.close();
    } catch (error) {
      try { await writable.abort(); } catch {}
      throw error;
    }
  };
  const installPackage = async (directory, release, backupName) => {
    const originals = new Map();
    for (const file of release.files) {
      const handle = await directory.getFileHandle(file.name);
      originals.set(file.name, await (await handle.getFile()).arrayBuffer());
    }
    const originalPage = new TextDecoder().decode(originals.get("index.html"));
    if (!originalPage.includes('id="draftsHome"') || !originalPage.includes("Reference Atelier")) {
      throw new Error("请选择当前生图工作台所在文件夹。");
    }
    const backup = await directory.getDirectoryHandle(backupName, { create: true });
    for (const [name, content] of originals) await writeFile(backup, name, content);
    const attempted = [];
    try {
      for (const file of release.files) {
        attempted.push(file.name);
        await writeFile(directory, file.name, new TextEncoder().encode(file.content));
      }
    } catch (error) {
      let restored = true;
      for (const name of attempted.reverse()) {
        try { await writeFile(directory, name, originals.get(name)); } catch { restored = false; }
      }
      throw new Error(restored
        ? `更新失败，已恢复旧版：${error.message}`
        : `更新失败，请从 ${backupName} 文件夹恢复程序文件：${error.message}`);
    }
  };
  if (typeof module !== "undefined" && module.exports) {
    module.exports = { FILES, compareVersions, validatePackage, installPackage };
    return;
  }
  const config = window.ATELIER_UPDATE || { version: "1.0.0", url: "" };
  const button = document.querySelector("#checkUpdateButton");
  if (!button) return;
  button.title = `当前版本 ${config.version}`;
  let updating = false;
  let pendingRelease = null;
  const busy = () => typeof activeBatchGenerationCount !== "undefined" && (activeBatchGenerationCount || pendingBatchGenerations.length || batchQueueRunning);
  button.addEventListener("click", async () => {
    if (updating) return;
    if (busy()) return window.alert("请等待生成任务结束，或先暂停批量任务并等待已提交任务返回，再更新。");
    if (!config.url) return window.alert("发布者尚未配置更新地址，请联系发布者完成首次发布。");
    if (!/^https:\/\/raw\.githubusercontent\.com\/[A-Za-z0-9_.-]+\/[A-Za-z0-9_.-]+\/main\/update\.json$/.test(config.url)) {
      return window.alert("更新地址不正确，请联系发布者。");
    }
    updating = true;
    button.disabled = true;
    const generateButton = document.querySelector("#batchGenerateButton");
    const previousDisabled = generateButton?.disabled;
    try {
      let release = pendingRelease;
      if (!release) {
        button.textContent = "检查中…";
        const controller = new AbortController();
        const timer = setTimeout(() => controller.abort(), 20000);
        try {
          const url = new URL(config.url);
          url.searchParams.set("check", Date.now());
          const response = await fetch(url, { cache: "no-store", credentials: "omit", signal: controller.signal });
          if (!response.ok) throw new Error(`更新地址返回 ${response.status}`);
          const text = await response.text();
          if (text.length > 4 * 1024 * 1024) throw new Error("更新包超过允许大小。");
          release = await validatePackage(JSON.parse(text), async (content) => {
            const hash = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(content));
            return [...new Uint8Array(hash)].map((byte) => byte.toString(16).padStart(2, "0")).join("");
          });
        } finally { clearTimeout(timer); }
        if (compareVersions(release.version, config.version) <= 0) return window.alert(`当前 ${config.version} 已是最新版本。`);
        pendingRelease = release;
        const path = decodeURIComponent(location.pathname.slice(0, location.pathname.lastIndexOf("/")));
        window.alert(`发现新版 ${release.version}\n${String(release.notes || "程序更新").slice(0, 2000)}\n\n请再次点击“立即更新”，选择当前工作台文件夹：\n${path}\n\n会备份并替换程序文件，保留浏览器中的草稿、图片和接口设置。`);
        return;
      }
      if (busy()) throw new Error("现在有生成任务，请等待任务结束后更新。");
      if (typeof window.showDirectoryPicker !== "function") throw new Error("请使用 Chrome 或 Edge，并通过启动生图工作台打开后更新。");
      const path = decodeURIComponent(location.pathname.slice(0, location.pathname.lastIndexOf("/")));
      const directory = await window.showDirectoryPicker({ id: "reference-atelier-install", mode: "readwrite" });
      if (busy()) throw new Error("现在有生成任务，请等待任务结束后更新。");
      const expectedName = path.split("/").filter(Boolean).pop();
      if (directory.name !== expectedName) throw new Error(`请选择文件夹“${expectedName}”。`);
      if (generateButton) generateButton.disabled = true;
      document.body.inert = true;
      button.textContent = "更新中…";
      if (typeof activeDraftId !== "undefined" && activeDraftId && batchPersistenceReady) {
        const saved = await Promise.all(Object.values(batchJobs).flat().map(persistBatchJob));
        if (saved.some((result) => !result)) throw new Error("当前任务记录未能保存，请解决存储问题后更新。");
        await persistBatchSettings();
      }
      await installPackage(directory, release, `.update-backup-${config.version}-${Date.now()}`);
      window.alert(`已更新到 ${release.version}，即将刷新工作台。`);
      location.reload();
    } catch (error) {
      if (error.name !== "AbortError") window.alert(`更新未完成：${error.message}`);
    } finally {
      updating = false;
      document.body.inert = false;
      button.disabled = false;
      button.textContent = pendingRelease ? `立即更新 ${pendingRelease.version}` : "检查更新";
      if (generateButton) generateButton.disabled = previousDisabled;
    }
  });
})();
